COLLDATA("tadabburar","ar",[[284,"§الإسراء\nwords\nالعَاجِلَةَالدُّنيَا.\nمَدحُورًامَطرُودًا مِن رَحمَةِ اللهِ.\nمَحظُورًامَمنُوعًا.\nمَخذُولًاغَيرَ مَنصُورٍ، وَلا مُعَانٍ مِنَ اللهِ.\nلِلأَوَّابِينَلِلرَّاجِعِينَ إِلَيهِ فِي كُلِّ وَقتٍ.\ndeeds\nقدم اليوم هديةً لوالديك وقل لهما قولًا يعجبهما.\nصل قرابتك اليوم بزيارة، أو مكالمة هاتفية، أو تصدق على أحد المحتاجين.\nاكتب رسالة تبيّن فيها خطر التبذير والإسراف.\nguid\nمجرد الرغبة في الآخرة لا يكفي، بل لا بد من الإيمان والعمل مع تلك الرغبة.\nيعطي الله تعالى الدنيا من يحب ومن لا يحب، وعطاؤه دائر بين التكريم والابتلاء والاستدراج.\nلا تنس أنك محاسب على المال.\nrefl\nثُمَّ جَعَلۡنَا لَهُۥ جَهَنَّمَ يَصۡلَىٰهَا مَذۡمُومٗا مَّدۡحُورٗا ١٨\nأي: في حالة الخزي والفضيحة والذم من الله ومن خلقه، والبعد عن رحمة الله؛ فيجمع له بين العذاب والفضيحة. السعدي:٤٥٥.\nفي جهنم عذاب نفسيٌّ وعذاب حِسِّي، وضح هذا في ضوء هذه الآية.\nوَمَنۡ أَرَادَ ٱلۡأٓخِرَةَ وَسَعَىٰ لَهَا سَعۡيَهَا وَهُوَ مُؤۡمِنٞ فَأُوْلَٰٓئِكَ كَانَ سَعۡيُهُم مَّشۡكُورٗا ١٩\nوفي الآية تنبيه على أن إرادة خير الآخرة من غير سعي غرور، وأن إرادة كل شيء لا بد لنجاحها من السعي في أسباب حصوله. ابن عاشور:١٥/٦٠.\nمن الغرور والغفلة أن تحب الخير ولا تسعى له، وضح هذا من الآية.\nوَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنًاۚ إِمَّا يَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَآ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفّٖ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلٗا كَرِيمٗا ٢٣\nوإنَّما خص حالة الكِبَر؛ لأنهما حينئذ أحوج إلى البر والقيام بحقوقهما لضعفهما. ابن جزي:١/٤٨٥.\nلم خص الله حالة الكِبَر بمزيد من البر مع أنه واجب على كل حال؟\nوَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنًاۚ إِمَّا يَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَآ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفّٖ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلٗا كَرِيمٗا ٢٣\n(أُف): معناها قول مكروه؛ يقال عند الضجر ونحوه، وإنَّما المراد بها أقل كلمة مكروهة تصدر من الإنسان، فنهى الله تعالى أن يقال ذلك للوالدين؛ فأولى وأحرى ألا يقال لهما ما فوق ذلك. ابن جزي:١/٤٨٥.\nتضمّن النهي عن كلمة (أُف) تحذيرًا شديدًا للولد، وضحه.\nوَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا ٢٤\nوفُهِمَ من هذا أنه كلما ازدادت التربية ازداد الحَقُّ، وكذلك من تولى تربية الإنسان في دينه ودنياه تربية صالحة غير الأبوين؛ فإن له على من رباه حق التربية. السعدي:٤٥٦.\nكثيرًا ما نسمع أن المعلم أبٌ ثانٍ، فما الحقُّ الذي يستحقه هذا المعلم؟\nوَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا ٢٤\nخص التربية بالذكر ليتذكر العبد شفقة الأبوين، وتعبهما في التربية؛ فيزيده ذلك إشفاقًا لهما، وحنانًا عليهما. القرطبي:١٣/٦٠.\nما سر ذكر تربية الوالدين للولد في الصغر؟\nوَلَا تُبَذِّرۡ تَبۡذِيرًا ٢٦ إِنَّ ٱلۡمُبَذِّرِينَ كَانُوٓاْ إِخۡوَٰنَ ٱلشَّيَٰطِينِۖ وَكَانَ ٱلشَّيۡطَٰنُ لِرَبِّهِۦ كَفُورٗا ٢٧\nمن أنفق ماله في الشهوات زائدة على قدر الحاجات، وعرضه بذلك للنفاد؛ فهو مبذر. القرطبي:١٣/٦٥.\nمتى يكون العبد مبذرًا لماله؟"],[285,"§الإسراء\nwords\nمَلُومًايَلُومُكَ النَّاسُ، وَيَذُمُّونَكَ.\nمَحسُورًافَارِغَ اليَدِ نَادِمًا، عَلَى تَبذِيرِكَ.\nوَيَقدِرُيُضَيِّقُ.\nإِملاقٍفَقرٍ.\nوَلا تَقفُلا تَتبَع.\nمَرَحًامُختالًا، مُتَكَبِّرًا.\ndeeds\nحدد سببًا يذكرك المعصية وابتعد عنه.\nاكفل يتيمًا أو أسهِم في كفالتة عن طريق إحدى المؤسسات الخيرية.\nقل: \"لا أعلم، لا أدري\"، وعود لسانك هذه الكلمة فيما لا تعرفه.\nguid\nابتعد عن الخطوات التي تؤدي بك إلى الوقوع في الفواحش والمعاصي؛ فإن من حام حول الحمى يوشك أن يقع فيه.\nأنت مسؤول يوم القيامة عن العهود والعقود التي عقدتها مع الله، أو مع خلقه؛ فاحرص على الوفاء بها.\nهذه الجوارح أنت مسؤول عنها أمام الله تعالى ولا يعرف قيمتها إلا من فقدها؛ فاستعملها في الطاعة.\nrefl\nوَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومٗا مَّحۡسُورًا ٢٩\n﴿وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ﴾: استعارة في معنى غاية البخل؛ كأن البخيل حبست يده عن الإعطاء، وشدت إلى عنقه. ﴿وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ﴾: استعارة في معنى غاية الجود. فنهى الله عن الطرفين وأمر بالتوسط بينهما؛ كقوله: ﴿وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا﴾ [الفرقان: ٦٧]. ابن جزي:١/٤٨٦.\nجعل الله هذه الشريعة وسطًا؛ مثّل لذلك بمثال.\nإِنَّ رَبَّكَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا ٣٠\nأي: خبير بصير بمن يستحق الغنى، ومن يستحق الفقر؛ فإن من العباد من لا يصلحه إلا الفقر، ولو غني لفسد عليه دينه، وإن من العباد لمن لا يصلحه إلا الغنى، ولو افتقر لفسد عليه دينه، وقد يكون الغنى في حق بعض الناس استدراجًا، والفقر عقوبةً -عياذًا بالله من هذا وهذا-. ابن كثير:٣/٣٧.\nما وجه ختم هذه الآية بوصفي (الخبير) و(البصير).\nوَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُمۡ خَشۡيَةَ إِمۡلَٰقٖۖ\nهذه الآية الكريمة دالة على أن الله تعالى أرحم بعباده من الوالد بولده. ابن كثير:٣/٣٧.\nمن أرحم بِكَ؟ ربُّك، أم والداك؟ ولماذا؟\nوَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ\nوالنهي عن قربانه أبلغ من النهي عن مجرد فعله؛ لأن ذلك يشمل النهي عن جميع مقدماته ودواعيه؛ فإن من حام حول الحمى يوشك أن يقع فيه، خصوصًا هذا الأمر الذي في كثير من النفوس أقوى داع إليه. السعدي:٤٥٧.\nما الفرق بين ﴿وَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ﴾ و\"لا تفعلوا الزنى\"؟ وأيهما أبلغ وأشد في النهي؟\nوَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَسَآءَ سَبِيلٗا ٣٢\nووصف الله الزنا وقبَّحه بأنه كان فاحشة أي: إثمًا يستفحش في الشرع والعقل والفطر؛ لتضمنه التجرؤ على الحرمة في حق الله، وحق المرأة، وحق أهلها أو زوجها، وإفساد الفراش، واختلاط الأنساب، وغير ذلك من المفاسد. السعدي:٤٥٧.\nما الأسباب التي جعلت الزنا يستحق الوصف بكونه فاحشة؟\nوَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُوْلَٰٓئِكَ كَانَ عَنۡهُ مَسۡـُٔولٗا ٣٦\nوهذا أدب خُلقي عظيم، وهو أيضًا إصلاح عقلي جليل؛ يعلم الأمة التفرقة بين مراتب الخواطر العقلية؛ بحيث لا يختلط عندها المعلوم والمظنون والموهوم. ابن عاشور:١٥/١٠١.\nأرشدت الآية الكريمة إلى أدب خلقي واصطلاح عقلي؛ بين ذلك.\nإِنَّكَ لَن تَخۡرِقَ ٱلۡأَرۡضَ وَلَن تَبۡلُغَ ٱلۡجِبَالَ طُولٗا ٣٧\nأي: مقدرتك لا تبلغ هذا المبلغ، بل أنت عبد ذليل، محاط بك من تحتك، ومن فوقك، والمحاط محصور ضعيف؛ فلا يليق بك التكبر. القرطبي:١٣/٨٣.\nلماذا لا يليق بالعبد الضعيف التكبر؟"],[286,"§الإسراء\nwords\nمَلُومًايَلُومُكَ النَّاسُ وَنَفسُكَ.\nمَدحُورًامَطرُودًا مُبعَدًا مِن رَحمَةِ اللهِ.\nأَفَأَصفَاكُمأَفَخَصَّكُم؟!\nصَرَّفنَانَوَّعنَا الأَسَالِيبَ، وَوَضَّحنَاهَا.\nأَكِنَّةًأَغطِيَةً.\nوَقرًاصَمَمًا وَثِقَلًا فِي السَّمعِ.\nوَرُفَاتًاأَجزَاءً مُفَتَّتَةً.\ndeeds\nاقرأ سورة من القرآن تذكرك الآخرة.\nادع الله تعالى باسميه: (الحليم)، و(الغفور) أن يعاملك بحلمه، وأن يغفر لك ويتجاوز عن سيئاتك.\nاستعذ بالله من شر الغفلة.\nguid\nأعظم القول وأشنعه ما كان فيه طعن في ذات الله تعالى.\nعدم فِقه القرآن وفهمه قد يكون عقوبةً بسبب المعاصي؛ فسارع إلى التوبة وكثرة الاستغفار.\nذكر الله تعالى -وخاصة كلمة التوحيد وقراءة القرآن- هو سبب لحفظ العبد من الشياطين.\nrefl\nأَفَأَصۡفَىٰكُمۡ رَبُّكُم بِٱلۡبَنِينَ وَٱتَّخَذَ مِنَ ٱلۡمَلَٰٓئِكَةِ إِنَٰثًاۚ إِنَّكُمۡ لَتَقُولُونَ قَوۡلًا عَظِيمٗا ٤٠\nوجَعله مجرد قول؛ لأنه لا يعدو أن يكون كلامًا صدر عن غير روية؛ لأنه لو تأمله قائله أدنى تأمل لوجده غير داخل تحت قضايا المقبول عقلًا. ابن عاشور:١٥/١٠٨.\nوصف المشركين للملائكة بأنهم بنات الله؛ لماذا عبرت عنه الآية الكريمة بأنه مجرد قول؟\nتُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا ٤٤\nولعل إيثار فعل: ﴿لَّا تَفۡقَهُونَ﴾ دون أن يقول: \"لا تعلمون\" للإشارة إلى أن المنفي علم دقيق. ابن عاشور:١٥/١١٥.\nلماذا قال: ﴿لَّا تَفۡقَهُونَ﴾، ولم يقل: \"لا تعلمون\"؟\nوَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ جَعَلۡنَا بَيۡنَكَ وَبَيۡنَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ حِجَابٗا مَّسۡتُورٗا ٤٥\nووصف الحجاب بالمستور مبالغة في حقيقة جنسه؛ أي: حجابًا بالغًا الغاية في حجب ما يحجبه هو، حتى كأنه مستور بساتر آخر... أو أريد أنه حجاب من غير جنس الحجب المعروفة؛ فهو حجاب لا تراه الأعين. ابن عاشور:١٥/١١٧.\nما فائدة تأكيد وصف الحجاب بالمستور في الآية الكريمة؟\nوَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ\nأي: أغطية وأغشية لا يفقهون معها القرآن، بل يسمعونه سماعًا تقوم به عليهم الحجة. السعدي:٤٥٩.\nما علامة وجود الغشاء أو الغطاء على القلب؟\nوَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ\nقوله: ﴿وَفِيٓ ءَاذَانِهِمۡ وَقۡرًاۚ﴾ أي: وجعل تعالى في آذان أولئك المشركين الخصوم ثقلًا في آذانهم؛ فلا يسمعون القرآن الذي يتلى عليهم؛ وهذا كله من الحجاب الساتر. والأكنة والوقر في الآذان عقوبة من الله تعالى لهم حرمهم بها من الهداية بالقرآن لسابقة الشر لهم، وما ظلمهم الله ولكن كانوا هم الظالمين ببغضهم للرسول وما جاء به، وحربهم له ولما جاء به من التوحيد والدين الحق. الجزائري:٣/١٩٩.\nما العقوبة المذكورة في الآية لمن أبغض ما جاء به الرسول -صلى الله عليه وسلم-؟\nوَإِذَا ذَكَرۡتَ رَبَّكَ فِي ٱلۡقُرۡءَانِ وَحۡدَهُۥ وَلَّوۡاْ عَلَىٰٓ أَدۡبَٰرِهِمۡ نُفُورٗا ٤٦\nقال أبو الجوزاء أوس بن عبد الله: \"ليس شيء أطرد للشيطان من القلب من قول: ﴿لَآ إِلَٰهَ إِلَّا ٱللَّهُ﴾\"، ثم تلا: ﴿وَإِذَا ذَكَرۡتَ رَبَّكَ فِي ٱلۡقُرۡءَانِ وَحۡدَهُۥ وَلَّوۡاْ عَلَىٰٓ أَدۡبَٰرِهِمۡ نُفُورًا﴾. القرطبي:١٣/٩٥.\nكيف تطرد الشيطان عن قلبك؟\nنَّحۡنُ أَعۡلَمُ بِمَا يَسۡتَمِعُونَ بِهِۦٓ\nأي: إنَّما منعناهم من الانتفاع عند سماع القرآن لأننا نعلم أن مقاصدهم سيئة؛ يريدون أن يعثروا على أقل شيء ليقدحوا به، وليس استماعهم لأجل الاسترشاد وقبول الحق، وإنَّما هم معتمدون على عدم اتباعه؛ ومن كان بهذه الحالة لم يفده الاستماع شيئًا. السعدي:٤٥٩.\nما الطريقة المثلى للإفادة من القرآن عند سماع آياته؟"],[287,"§الإسراء\nwords\nفَسَيُنغِضُونَيُحَرِّكُونَ مُستَهزِئِينَ.\nيَنزَغُيُفسِدُ.\nيَبتَغُونَيَطلُبُونَ.\nالوَسِيلَةَالقُربَةَ بِالطَّاعَةِ.\nالكِتَابِاللَّوحِ المَحفُوظِ.\nمَسطُورًامَكتُوبًا.\ndeeds\nقل لأخيك أو لزميلك قولًا حسنًا؛ لتزيد فيه من الألفة والمحبة بينكما.\nاستعذ بالله من نزغات الشيطان.\nاحـرص اليـوم عـلى كتــابة وصيتـك تـطبيقًـا لأمـر الـرسـول -صلى الله عليه وسلم-.\nguid\nعود لسانك التزام الكلام الحسن.\nمحبة الله سبحانه، ورجاؤه، والخوف منه؛ هذه الأعمال القلبية الثلاثة هي أصل لكل خير؛ لأجل ذلك وصف الله بها المقربين عنده.\nإذا كثر الخبث قرب الهلاك.\nrefl\nوَيَقُولُونَ مَتَىٰ هُوَۖ قُلۡ عَسَىٰٓ أَن يَكُونَ قَرِيبٗا ٥١\nفليس في تعيين وقته فائدة، وإنَّما الفائدة والمدار على تقريره، والإقرار به، وإثباته؛ وإلا فكل ما هو آتٍ فإنه قريب. السعدي:٤٦٠.\nسؤال المشركين عن وقت يوم القيامة سؤال في غير محله، فلماذا؟\nيَوۡمَ يَدۡعُوكُمۡ فَتَسۡتَجِيبُونَ بِحَمۡدِهِۦ وَتَظُنُّونَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗا ٥٢\nلأن الإنسان لو مكث ألوفًا من السنين في الدنيا وفي القبر عد ذلك قليلًا في مدة القيامة والخلود؛ قال قتادة: \"يستحقرون مدة الدنيا في جنب القيامة\". البغوي:٢/٦٨٧.\nلماذا يظن العبد يوم القيامة أن مكوثه في الدنيا كان قليلًا؟\nوَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ\nإذا دار الأمر بين أمرين حسنين فإنه يؤمر بإيثار أحسنهما إن لم يمكن الجمع بينهما. والقول الحسن داعٍ لكل خلق جميل وعمل صالح؛ فإن مَن مَلَكَ لسانه مَلَكَ جميع أمره. السعدي:٤٦٠.\nما الفرق بين القول الحسن والأحسن، وأيهما أُمرنا به؟\nوَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ ٱلشَّيۡطَٰنَ يَنزَغُ بَيۡنَهُمۡۚ\nأي: يسعى بين العباد بما يفسد عليهم دينهم ودنياهم، فدواء هذا أن لا يطيعوه في الأقوال غير الحسنة التي يدعوهم إليها، وأن يلينوا فيما بينهم؛ لينقمع الشيطان الذي ينزغ بينهم؛ فإنه عدوهم الحقيقي الذي ينبغي لهم أن يحاربوه. السعدي:٤٦٠.\nالشيطان يدخل في المحادثة بينك وبين الناس، فكيف تعالج ذلك؟\nوَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ ٱلشَّيۡطَٰنَ يَنزَغُ بَيۡنَهُمۡۚ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلۡإِنسَٰنِ عَدُوّٗا مُّبِينٗا ٥٣\nوالمقصد الأهم من هذا التأديب تأديب الأمة في معاملة بعضهم بعضًا بحسن المعاملة وإلانةِ القول؛ لأن القول ينم عن المقاصد... ثم تأديبهم في مجادلة المشركين اجتنابًا لما تثيره المشادّة والغلظة من ازدياد مكابرة المشركين وتصلبهم؛ فذلك من نزغ الشيطان بينهم وبين عدوهم. ابن عاشور:١٥/١٣٢.\nما المقصود الأهم في الآية الكريمة؟\nأُوْلَٰٓئِكَ ٱلَّذِينَ يَدۡعُونَ يَبۡتَغُونَ إِلَىٰ رَبِّهِمُ ٱلۡوَسِيلَةَ أَيُّهُمۡ أَقۡرَبُ وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ\nلا تتم العبادة إلا بالخوف والرجاء؛ فبالخوف ينكف عن المناهي، وبالرجاء يكثر من الطاعات. ابن كثير:٣/٤٦.\nما أهمية الرجاء والخوف في حياة المؤمن؟\nوَإِن مِّن قَرۡيَةٍ إِلَّا نَحۡنُ مُهۡلِكُوهَا قَبۡلَ يَوۡمِ ٱلۡقِيَٰمَةِ أَوۡ مُعَذِّبُوهَا عَذَابٗا شَدِيدٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا ٥٨\nقال ابن مسعود -رضي الله عنه-: \"إذا ظهر الزنى والربا في قرية أذن الله في هلاكهم\". القرطبي:١٣/١٠٧.\nمتى يهلك الله تعالى القرى؟"],[288,"§الإسراء\nwords\nأَرَأَيتَكَأَخبِرنِي.\nلأَحتَنِكَنَّلَأَستَولِيَنَّ عَلَيهِم.\nمَوفُورًاوَافِرًا.\nوَاستَفزِزاستَخِفَّ، وَاستَعجِل.\nوَأَجلِباجمَع، وَصِح عَلَيهِم.\nبِخَيلِكَ وَرَجِلِكَبِجُنُودِكَ الرَّاكِبِينَ وَالرَّاجِلِينَ فِي مَعصِيَةِ اللهِ.\ndeeds\nأرسل رسالة عن خطر الغناء والموسيقى، وأنها من خطوات الشيطان.\nاحرص اليوم على أذكار الصباح والمساء، وأذكار الطعام، والدخول والخروج من المنزل.\nادع الله تعالى أن يجعلك من عباده الذين ليس للشيطان عليهم سبيلٌ.\nguid\nما أحلم الله على عباده؛ يعصونه وهو محيط بهم.\nمن لم يحرص على مراعاة أحكام الشرع في أمواله، وأولاده، وطعامه؛ فقد شاركه الشيطان فيها.\nابحث عن صفات الذين ليس للشيطان عليهم سلطان، واحرص أن تكون منهم.\nrefl\nوَءَاتَيۡنَا ثَمُودَ ٱلنَّاقَةَ مُبۡصِرَةٗ فَظَلَمُواْ بِهَاۚ وَمَا نُرۡسِلُ بِٱلۡأٓيَٰتِ إِلَّا تَخۡوِيفٗا ٥٩\nوخص بالذكر ثمود وآيتها لشهرة أمرهم بين العرب، ولأن آثار هلاكهم في بلاد العرب قريبَة من أهل مكة؛ يبصرها صادرهم وواردهم في رحلاتهم بين مكة والشام. ابن عاشور:١٥/١٤٤.\nلماذا خصت ثمود بالذكر في الآية الكريمة؟\nوَمَا جَعَلۡنَا ٱلرُّءۡيَا ٱلَّتِيٓ أَرَيۡنَٰكَ إِلَّا فِتۡنَةٗ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ فِي ٱلۡقُرۡءَانِۚ وَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنٗا كَبِيرٗا ٦٠\nلما أخبرهم بالإسراء وشجرة الزقوم أنكر ذلك طائفة منهم، وزعموا أن العقل ينفي ذلك، وأنزل الله تعالى: (وما جعلنا الرؤيا التي أريناك إلا فتنة للناس والشجرة الملعونة في القرآن)...أي: محنة وابتلاء للناس؛ ليتميّز المؤمن عن الكافر، وكان فيما أخبرهم به أنّه رأى الجنَّة والنَّار، وهذا ممّا يُخوّفهم به؛ قال تعالى: ﴿وَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنًا كَبِيرًا﴾. ابن تيمية:٤/٢٣٥.\nكيف كان ما رآه النبي وأخبر به فتنة للناس؟ وضح ذلك من خلال الوقفة.\nوَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنٗا كَبِيرٗا ٦٠\nوقد اختير الفعل المضارع في: (نخوفهم) و (يزيدهم) لاقتضائه تكرر التخويف وتجدده، وأنه كلما تجدد التخويف تجدد طغيانهم وعظم. ابن عاشور:١٥/١٤٩.\nلماذا اختير الفعل المضارع (نخوفهم) و(يزيدهم) في الآية الكريمة؟\nقَالَ أَرَءَيۡتَكَ هَٰذَا ٱلَّذِي كَرَّمۡتَ عَلَيَّ لَئِنۡ أَخَّرۡتَنِ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَأَحۡتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلٗا ٦٢\n﴿لَأَحۡتَنِكَنَّ ذُرِّيَّتَهُۥٓ﴾ معناه: لأستولين عليهم، ولأقودنهم؛ وهو مأخوذ من تحنيك الدابة؛ وهو أن يشدّ على حنكها بحبل فتنقاد. ابن جزي:١/٤٩١.\nما المقصود باحتناك الشيطان للإنسان؟ وما علامته؟\nوَٱسۡتَفۡزِزۡ مَنِ ٱسۡتَطَعۡتَ مِنۡهُم بِصَوۡتِكَ\nوصوته: كل داع يدعو إلى معصية الله تعالى؛ فعن ابن عباس- رضي الله عنهما- ومجاهد: \"الغناء والمزامير واللهو\". القرطبي:١٣/١١٨.\nكيف يكون استفزاز الشيطان بصوته؟\nوَٱسۡتَفۡزِزۡ مَنِ ٱسۡتَطَعۡتَ مِنۡهُم بِصَوۡتِكَ وَأَجۡلِبۡ عَلَيۡهِم بِخَيۡلِكَ وَرَجِلِكَ\nكل متكلم بغير طاعة الله، ومصوت بيراعٍ أو مزمار أو دُفٍّ حرام أو طبل؛ فذلك صوت الشيطان، وكل ساعٍ في معصية الله على قدميه فهو من رَجلِه، وكل راكب في معصية الله فهو من خيَّالته. ابن القيم:٢/١٤٢-١٤٣.\nوضح المقصود بصوت الشيطان، وخيله، ورجِله.\nوَشَارِكۡهُمۡ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِ وَعِدۡهُمۡۚ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا ٦٤\nمشاركته في الأموال: بكسبها من الربا، وإنفاقها في المعاصي، وغير ذلك. ومشاركته في الأولاد هي: بالاستيلاد بالزنا، وتسمية الولد \"عبد شمس\" و\"عبد الحارث\"، وشبه ذلك. ابن جزي:١/٤٩٢.\nعدد مظاهر من مشاركة الشيطان لبني آدم في المال، والولد."],[289,"§الإسراء\nwords\nحَاصِبًارِيحًا شَدِيدَةً تَرمِيكُم بالحَصبَاءِ.\nقَاصِفًا مِنَ الرِّيحِرِيحًا شَدِيدَةً لا تَمُرُّ عَلَى شَيءٍ إِلاَّ كَسَرَتهُ.\nبِإِمَامِهِمبِمَن كَانُوا يَقتَدُونَ بِهِ فِي الدُّنيَا.\nكَادُواقَارَبُوا.\nلَيَفتِنُونَكَلَيَصرِفُونَكَ، وَيُوقِعُونَكَ فِي الفِتنَةِ.\ndeeds\nتذكر موقفًا أنجاك الله فيه، ثم اشكر الله عليه.\nسل الله تعالى أن تؤتى كتابك بيمينك.\nرسول الله -صلى الله عليه وسلم- احتاج لتثبيت الله له؛ فادع أنت بهذا الدعاء: \"اللهم إني أسألك الثبات في الأمر، والعزيمة على الرشد\".\nguid\nمن ضعف العبد أنه بعد إنجاء الله تعالى له وتفريج كربته، فإنه سرعان ما يعود إلى غفلته وإعراضه وفساده.\nلا تحتقر أحدًا لِلون، أو نسب، أو بلد.\nلا يتخذُك المجرمون صديقًا إلا إذا شاركتهم معاصيهم.\nrefl\nأَفَأَمِنتُمۡ أَن يَخۡسِفَ بِكُمۡ جَانِبَ ٱلۡبَرِّ أَوۡ يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗا ثُمَّ لَا تَجِدُواْ لَكُمۡ وَكِيلًا ٦٨\nفي هذا تنبيه على أن السلامة في البَرِّ نعمة عظيمة تنسونها؛ فلو حدث لكم خسف لهلكتم هلاكًا لا نجاة لكم منه، بخلاف هول البحر. ابن عاشور:١٥/١٦٢.\nالسلامة في البَرِّ نعمة عظيمة ننساها كثيرًا، كيف أرشدت الآية الكريمة إلى ذلك؟\nوَفَضَّلۡنَٰهُمۡ عَلَىٰ كَثِيرٖ مِّمَّنۡ خَلَقۡنَا تَفۡضِيلٗا ٧٠\nالصحيح الذى يعول عليه: أن التفضيل إنَّما كان بالعقل الذي هو عمدة التكليف، وبه يعرف الله، ويفهم كلامه، ويوصل إلى نعيمه وتصديق رسله، إلا أنه لمَّا لم ينهض بكل المراد من العبد بعثت الرسل، وأنزلت الكتب؛ فمثال الشرع الشمس، ومثال العقل العين؛ فإذا فتحت وكانت سليمة رأت الشمس، وأدركت تفاصيل الأشياء. القرطبي ١٣/١٢٦.\nبيّن بأي شيء فضل الله تعالى بني آدم على سائر المخلوقات.\nيَوۡمَ نَدۡعُواْ كُلَّ أُنَاسِۢ بِإِمَٰمِهِمۡۖ فَمَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُوْلَٰٓئِكَ يَقۡرَءُونَ كِتَٰبَهُمۡ وَلَا يُظۡلَمُونَ فَتِيلٗا ٧١\nالفتيل هو الخيط الذي في شق نواة التمرة، والمعنى أنهم لا يظلمون من أعمالهم قليلًا ولا كثيرًا؛ فعبر بأقل الأشياء تنبيهًا على الأكثر. ابن جزي:١/٤٩٣.\nما وجه التعبير بالفتيل في الآية؟\nوَمَن كَانَ فِي هَٰذِهِۦٓ أَعۡمَىٰ فَهُوَ فِي ٱلۡأٓخِرَةِ أَعۡمَىٰ وَأَضَلُّ سَبِيلٗا ٧٢\nالإشارة بـ(هذه) إلى الدنيا، والعمى يراد به عمى القلب؛ أي: من كان في الدنيا أعمى عن الهدى والصواب فهو في يوم القيامة أعمى؛ أي: حيران، يائس من الخير. ابن جزي:١/٤٩٣.\nما المقصود بعمى الدنيا، وعمى الآخرة؟\nوَإِن كَادُواْ لَيَفۡتِنُونَكَ عَنِ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ لِتَفۡتَرِيَ عَلَيۡنَا غَيۡرَهُۥۖ وَإِذٗا لَّٱتَّخَذُوكَ خَلِيلٗا ٧٣\nولكن لتعلم أنهم لم يعادوك وينابذوك العداوة إلا للحق الذي جئت به، لا لذاتك. السعدي:٤٦٤.\nما سبب معاداة المشركين للنبي -صلى الله عليه وسلم-؟ وكيف يفيد الداعية من هذا الأمر؟\nوَلَوۡلَآ أَن ثَبَّتۡنَٰكَ لَقَدۡ كِدتَّ تَرۡكَنُ إِلَيۡهِمۡ شَيۡـٔٗا قَلِيلًا ٧٤\nفي هذه الآيات دليل على شدة افتقار العبد إلى تثبيت الله إياه، وأنه ينبغي له أن لا يزال متملقًا لربه أن يثبته على الإيمان، ساعيًا في كل سبب موصل إلى ذلك؛ لأن النبي -صلى الله عليه وسلم-، وهو أكمل الخلق، قال الله له: (ولولا أن ثبتناك لقد كدت تركن إليهم شيئًا قليلًا)؛ فكيف بغيره؟! السعدي:٤٦٤.\nفي هذه الآيات دليل على شدة افتقار العبد إلى تثبيت الله إياه، وضح ذلك.\nإِذٗا لَّأَذَقۡنَٰكَ ضِعۡفَ ٱلۡحَيَوٰةِ وَضِعۡفَ ٱلۡمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيۡنَا نَصِيرٗا ٧٥\nبحسب علو مرتبة العبد، وتواتر النِّعَمِ عليه من الله يعظم إثمه، ويتضاعف جرمه إذا فعل ما يلام عليه؛ لأن الله ذكَّر رسوله لو فعل -وحاشاه من ذلك- بقوله: (إذًا لأذقناك ضعف الحياة وضعف الممات ثم لا تجد لك علينا نصيرًا). السعدي:٤٦٤.\nما سبب كون الخطأ من النبي أو العالم أو الداعية -لو حصل- أعظم من خطأ غيرهم؟"],[290,"§الإسراء\nwords\nكَادُواقَارَبُوا.\nتَحوِيلًاتَغيِيرًا.\nلِدُلُوكِ الشَّمسِمِن وَقتِ زَوَالِ الشَّمسِ عِندَ الظَّهِيرَةِ.\nغَسَقِ اللَّيلِظُلمَتِهِ.\nوَزَهَقَبَطَلَ، وَاضمَحَلَّ.\nزَهُوقًالا بَقَاءَ لَهُ، وَلا ثَبَاتَ.\nوَنَأَى بِجَانِبِهِتَبَاعَدَ عَن طَاعَةِ رَبِّهِ كِبرًا، وَعِنَادًا.\nشَاكِلَتِهِطَرِيقَتِهِ، وَمَا يَلِيقُ بِهِ.\ndeeds\nحافظ على أداء الصلوات الخمس في المسجد؛ خاصة صلاة الفجر.\nقم هذه الليلة من الليل ما تيسر، ثم أوتر.\nارقِ نفسك أو من حولك بالقرآن.\nguid\nالقرآن شفاء ورحمة للمؤمنين خاصة؛ فاستشفِ به من أمراضك الحسية والمعنوية.\nمتى ما قام أهل الحق بنشره فلا بد أن يضمحل الباطل مهما انتفش.\nإياك والظلم؛ فبقدر الظلم يمنع الظالم من الانتفاع بالقرآن.\nrefl\nوَإِن كَادُواْ لَيَسۡتَفِزُّونَكَ مِنَ ٱلۡأَرۡضِ لِيُخۡرِجُوكَ مِنۡهَاۖ وَإِذٗا لَّا يَلۡبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلٗا ٧٦\nأي: لو أخرجوك لم يلبثوا بعد خروجك بمكة إلا قليلًا. فلما خرج النبي -صلى الله عليه وسلم- مهاجرًا من مكة إلى المدينة لأجل إذاية قريش له ولأصحابه؛ لم يبقوا بعد ذلك إلا قليلًا، وقتلوا يوم بدر. ابن جزي:١/٤٩٤.\nبيّن سنة الله -عز وجل- فيمن آذى الدعاة والمصلحين.\nوَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةٗ لَّكَ عَسَىٰٓ أَن يَبۡعَثَكَ رَبُّكَ مَقَامٗا مَّحۡمُودٗا ٧٩\nوفي صحيح البخاري عن ابن عمر: \"إن الناس يصيرون يوم القيامة جُثًا... -أي: جماعات- كل أمة تتبع نبيها؛ يقولون: يا فلان اشفع؛ حتى تنتهي الشفاعة إلى النبي؛ فذلك يوم يبعثه الله المقام المحمود\". ابن عاشور:١٥/١٨٥.\nما المقصود بالمقام المحمود؟\nوَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةٗ لَّكَ عَسَىٰٓ أَن يَبۡعَثَكَ رَبُّكَ مَقَامٗا مَّحۡمُودٗا ٧٩\nقيام الليل فيه الخلوة مع البارئ، والمناجاة دون الناس. القرطبي:١٣/١٥١.\nبم يتميز قيام الليل عن بقية العبادات؟\nوَقُلۡ جَآءَ ٱلۡحَقُّ وَزَهَقَ ٱلۡبَٰطِلُۚ إِنَّ ٱلۡبَٰطِلَ كَانَ زَهُوقٗا ٨١\n﴿إِنَّ ٱلۡبَٰطِلَ كَانَ زَهُوقًا﴾ أي: هذا وصف الباطل، ولكنه قد يكون له صولة وروجان إذا لم يقابله الحق؛ فعند مجيء الحق يضمحل الباطل، فلا يبقى له حراك، ولهذا لا يروج الباطل إلا في الأزمان والأمكنة الخالية من العلم بآيات الله وبيناته. السعدي:٤٦٥.\nمتى يكون للباطل قوة ومكانة؟\nوَقُلۡ جَآءَ ٱلۡحَقُّ وَزَهَقَ ٱلۡبَٰطِلُۚ إِنَّ ٱلۡبَٰطِلَ كَانَ زَهُوقٗا ٨١\nودل فعل (كان) على أن الزُهوق شنشنة الباطل، وشأنه في كل زمان أنه يظهر ثم يضمحل. ابن عاشور:١٥/١٨٨.\nماذا يفيد الفعل (كان) في الآية الكريمة؟\nوَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَآءٞ وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ\nفالشفاء الذي تضمنه القرآن عامٌّ لشفاء القلوب من الشُّبَه، والجهالة، والانحراف السيئ، والقصود السيئة؛ فإنه مشتمل على العلم اليقيني الذي تزول به كل شبهة وجهالة، والوعظ والتذكير الذي يزول به كل شهوة تخالف أمر الله، ولشفاء الأبدان من آلامها وأشقامها. السعدي:٤٦٥.\nما وجه كون القرآن شفاءً للقلوب؟\nوَيَسۡـَٔلُونَكَ عَنِ ٱلرُّوحِۖ قُلِ ٱلرُّوحُ مِنۡ أَمۡرِ رَبِّي وَمَآ أُوتِيتُم مِّنَ ٱلۡعِلۡمِ إِلَّا قَلِيلٗا ٨٥\nفي هذه الآية دليل على أن المسؤول إذا سُئِلَ عن أمرٍ الأَولَى بالسائل غيره أن يعرض عن جوابه، ويدله على ما يحتاج إليه، ويرشده إلى ما ينفعه. السعدي:٤٦٦.\nيكثر في الناس أن يسألوا عن أمورٍ لا تفيدهم في دينهم ولا دنياهم، فكيف يتصرف الداعية وطالب العلم مع مثل هذه الأسئلة؟"],[291,"§الإسراء\nwords\nظَهِيرًامُعِينًا.\nصَرَّفنَانَوَّعنَا وَبَيَّنَّا.\nصَرَّفنَانَوَّعنَا وَبَيَّنَّا.\nكِسَفًاقِطَعًا.\nقَبِيلًانُشَاهِدُهُم مُقَابَلَةً وَعِيَانًا.\nزُخرُفٍذَهَبٍ.\ndeeds\nعدِّد خمسًا من أكبر فضائل الله تعالى عليك، ثم أكثر من شكر الله عليها.\nاقرأ مثلًا قرآنيًا، ثم استنبط منه فائدة.\nابحث عن ترجمة لمعاني القرآن وأعطها لكافر لعله يسلم بسببك.\nguid\nنوَّعَ الله في هذا القرآن المواعظ والأمثال ليتحقق المقصود منها.\nتعلم فن الحوار والجدال وتدرب عليه.\nكلما اشتدت عليك الأمور اقرأ في السيرة النبوية حتى تقتدي بصبره.\nrefl\nإِلَّا رَحۡمَةٗ مِّن رَّبِّكَۚ إِنَّ فَضۡلَهُۥ كَانَ عَلَيۡكَ كَبِيرٗا ٨٧\nإذ جعلك سيد ولد آدم، وأعطاك المقام المحمود، وهذا الكتاب العزيز. القرطبي:١٣/١٦٩.\nما الفضائل الكريمة التي أكرم الله تعالى بها نبيه -صلى الله عليه وسلم-؟\nقُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٖ ظَهِيرٗا ٨٨\nعجِز الخلق عن الإتيان بمثله لما تضمنه من العلوم الإلهية والبراهين الواضحة والمعاني العجيبة؛ التي لم يكن الناس يعلمونها ولا يصلون إليها، ثم جاءت فيه على الكمال. وقال أكثر الناس: إنهم عجزوا عنه لفصاحته، وحسن نظمه. ووجوه إعجازه كثيرة. ابن جزي:١/٤٩٦.\nبيّن بعض أوجه إعجاز القرآن من الآية.\nقُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٖ ظَهِيرٗا ٨٨\nوهذا دليل قاطع، وبرهان ساطع، على صحة ما جاء به الرسول وصدقه؛ حيث تحدى الله الإنس والجن أن يأتوا بمثله، وأخبر أنهم لا يأتون بمثله، ولو تعاونوا كلهم على ذلك لم يقدروا عليه، ووقع كما أخبر الله. السعدي:٤٦٦.\nكيف تدل الآية على صدق رسالة محمد -صلى الله عليه وسلم- ؟\nقُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٖ ظَهِيرٗا ٨٨\nفالقرآن معجز في النظم والتأليف، والإخبار عن الغيوب، وهو في أعلى طبقات البلاغة، لا يشبه كلام الخلق؛ لأنه غير مخلوق، ولو كان مخلوقًا لأتوا بمثله. البغوي:٢/٧١٤\nبيّن ما اشتمل عليه القرآن الكريم من إعجاز.\nوَقَالُواْ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ ٱلۡأَرۡضِ يَنۢبُوعًا ٩٠\nوذلك سهل على الله تعالى يسير، لو شاء لفعله، ولأجابهم إلى جميع ما سألوا وطلبوا، ولكن علم أنهم لا يهتدون. ابن كثير:٣/٦٣.\nلماذا لم يستجب الله لطلبات المشركين؟\nأَوۡ تُسۡقِطَ ٱلسَّمَآءَ كَمَا زَعَمۡتَ عَلَيۡنَا كِسَفًا\nأي: أنك وعدتنا أن يوم القيامة تنشق فيه السماء وتَهِي، وتدلى أطرافها؛ فعجِّل ذلك في الدنيا، وأسقطها كسفًا... وأمَّا نبي الرحمة ونبي التوبة المبعوث رحمة للعالمين فسأل إنظارهم وتأجيلهم؛ لعل الله أن يخرج من أصلابهم من يعبد الله لا يشرك به شيئًا، وكذلك وقع؛ فإن من هؤلاء الذين ذُكروا من أسلم بعد ذلك وحسن إسلامه. ابن كثير:٣/٦٣.\nلماذا لم يدعُ النبي ربه أن يسقط السماء كِسَفًا على هؤلاء المعاندين الذين طلبوا ذلك؟\nقُل لَّوۡ كَانَ فِي ٱلۡأَرۡضِ مَلَٰٓئِكَةٞ يَمۡشُونَ مُطۡمَئِنِّينَ لَنَزَّلۡنَا عَلَيۡهِم مِّنَ ٱلسَّمَآءِ مَلَكٗا رَّسُولٗا ٩٥\n﴿قُل لَّوۡ كَانَ فِي ٱلۡأَرۡضِ مَلَٰٓئِكَةٌ يَمۡشُونَ مُطۡمَئِنِّينَ﴾: مستوطنين مقيمين. ﴿لَنَزَّلۡنَا عَلَيۡهِم مِّنَ ٱلسَّمَآءِ مَلَكًا رَّسُولًا﴾: من جنسهم؛ لأن القلب إلى الجنس أميل منه إلى غير الجنس. البغوي:٢/٧١٧.\nلماذا جعل الله تعالى الأنبياء للبشر من جنسهم، ولم يجعلهم ملائكة؟"],[292,"§الإسراء\nwords\nخَبَتسَكَنَ لَهِيبُهَا.\nقَتُورًامُبَالِغًا فِي البُخلِ.\nبَصَائِرَدلائلَ تَدُلُّ أهلَ البَصِيرَةِ عَلَى وَحدَانِيَّةِ اللهِ، وَعَلَى صِدقِي.\nمَثبُورًاهَالِكًا مَغلُوبًا مَلعُونًا.\nلَفِيفًاجَمِيعًا.\ndeeds\nأسبغ الوضوء على جوارحك لعله يكون سببًا في تكفير ذنوبها.\nسل الله تعالى أن يغنيك بفضله عمن سواه.\nأنفق في أحد أوجه الخير لتعود نفسك على الكرم.\nguid\nالإنسان مهما بلغ من الكرم والعطاء فإن الأصل فيه الإمساك، والله سبحانه هو الكريم المنان، المعطي بدون حساب.\nكلما عظم مقام الرب في قلب العبد هان عليه مقام المخلوقين.\nمهما اشتد الأذى فاصبر؛ فإن العاقبة للمتقين.\nrefl\nوَمَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن يُضۡلِلۡ فَلَن تَجِدَ لَهُمۡ أَوۡلِيَآءَ مِن دُونِهِۦۖ\nأي: لو هداهم الله لاهتدوا. ﴿وَمَن يُضۡلِلۡ فَلَن تَجِدَ لَهُمۡ أَوۡلِيَآءَ مِن دُونِهِۦۖ﴾ أي: لا يهديهم أحد. القرطبي: ١٣/١٧٨.\nهل يستطيع أحد أن يصل إلى الهداية بغير إرادة الله تعالى؟\nوَنَحۡشُرُهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡيٗا وَبُكۡمٗا وَصُمّٗاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ\nيُسحبون يوم القيامة على وجوههم إلى جهنم كما يُفعل في الدنيا بمن يُبالغ في هوانه وتعذيبه. وهذا هو الصحيح؛ لحديث أنس: أن رجلًا قال: يا رسول الله، ﴿ٱلَّذِينَ يُحۡشَرُونَ عَلَىٰ وُجُوهِهِمۡ﴾؛ أيحشر الكافر على وجهه؟! قال رسول الله -صلى الله عليه وسلم-: «أليس الذي أمشاه على الرجلين قادرًا على أن يمشيه على وجهه يوم القيامة؟!» قال قتادة حين بلغه: \"بلى وعزة ربنا\" أخرجه البخاري ومسلم. القرطبي: ١٣/١٧٨\nكيف يحشر الكفار على وجوههم يوم القيامة؟ وما دلالة ذلك؟\nوَنَحۡشُرُهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡيٗا وَبُكۡمٗا وَصُمّٗاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ كُلَّمَا خَبَتۡ زِدۡنَٰهُمۡ سَعِيرٗا ٩٧\nوهذا جزاء مناسب للجرم؛ لأنهم روّجوا الضلالة في صورة الحق، ووسموا الحق بسمات الضلال، فكان جزاؤهم أن حولت وجوههم أعضاءَ مشي عِوضًا عن الأرجل، ثم كانوا ﴿عُمۡيًا وَبُكۡمًا﴾ جزاء أقوالهم الباطلة على الرسول وعلى القرآن، و(صُمًّا) جزاء امتناعهم من سماع الحق. ابن عاشور: ١٥/٢١٧.\nجزاء الكفار يوم القيامة مناسب لجرمهم، بيّن ذلك.\nوَنَحۡشُرُهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡيٗا وَبُكۡمٗا وَصُمّٗاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ كُلَّمَا خَبَتۡ زِدۡنَٰهُمۡ سَعِيرٗا ٩٧\nفإن قيل: كيف وصفهم بأنهم عميٌ وبكمٌ وصمٌ، وقد قال: ﴿وَرَءَا ٱلۡمُجۡرِمُونَ ٱلنَّارَ فَظَنُّوٓاْ﴾ [الكهف: ٥٣]؛ أثبت لهم الرؤية والكلام والسمع؟! قيل: يُحشرون على ما وصفهم اللّه، ثم تعاد إليهم هذه الأشياء. وجواب آخر: قال ابن عباس -رضي الله عنهما-: \"﴿عُمۡيًا وَبُكۡمًا﴾: لا يرون ما يسرهم، كما لا ينطقون بحجة، (وَصُمًّا) لا يسمعون شيئًا يسرهم\"، وقال الحسن: \"هذا حين يساقون إلى الموقف إلى أن يدخلوا النار\". البغوي: ٢/٧١٨.\nكيف يحشر أهل النار ﴿عُمۡيًا وَبُكۡمًا وَصُمًّاۖ﴾؟\nوَكَانَ ٱلۡإِنسَٰنُ قَتُورٗا ١٠٠\nأي: بخيلًا ممسكًا عن الإنفاق. البغوي: ٢/٧١٩.\nبيّن صفة الإنسان الجبلية في المال، وكيف ينجو العبد من ذلك؟\nقَالَ لَقَدۡ عَلِمۡتَ مَآ أَنزَلَ هَٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ بَصَآئِرَ وَإِنِّي لَأَظُنُّكَ يَٰفِرۡعَوۡنُ مَثۡبُورٗا ١٠٢\nفموسى وهو الصادق المصدوق يقول: ﴿لَقَدۡ عَلِمۡتَ مَآ أَنزَلَ هَٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ بَصَآئِرَ﴾؛ فدل على أن فرعون كان عالمًا بأن الله أنزل الآيات، وهو من أكبر خلق الله عنادًا وبغيًا؛ لفساد إرادته وقصده، لا لعدم علمه. ابن تيمية: ٤/٢٤٨.\nقد يضل الإنسان وهو يعلم، بيّن ذلك من خلال الآية.\nفَأَرَادَ أَن يَسۡتَفِزَّهُم مِّنَ ٱلۡأَرۡضِ فَأَغۡرَقۡنَٰهُ وَمَن مَّعَهُۥ جَمِيعٗا ١٠٣\nفقد أضمر المشركون إخراج النبي والمسلمين من مكة؛ فمثلت إرادتهم بإرادة فرعون إخراج موسى وبني إسرائيل من مصر. ابن عاشور: ١٥/٢٢٨.\nهناك تشابه بين مشركي قريش وقوم فرعون، وضحه."],[293,"§الكهف ، الإسراء\nwords\nفَرَقنَاهُبَيَّنَّاهُ، وَفَصَّلنَاهُ؛ فَارِقًا بَينَ الهُدَى وَالضَّلالِ.\nمُكثٍتُؤَدَةٍ، وَتَمَهُّلٍ.\nيَخِرُّونَ لِلأَذقَانِيَسجُدُونَ عَلَى وُجُوهِهِم.\nوَلا تُخَافِتولا تُسِرَّ بِهَا.\nعِوَجًامَيلًا عَنِ الحَقِّ.\nمِن لَدُنهُمِن عِندِهِ.\ndeeds\nاحفظ أول عشر آيات من سورة الكهف؛ فقد قال -صلى الله عليه وسلم-: «من حفظ عشر آيات من أول سورة الكهف عصم من الدجال» [صحيح مسلم].\nاجتمع مع بعض زملائك، وليقرأ كل واحد آيات من كتاب الله سبحانه.\nتأمل معاني بعض أسماء الله، ثم ادعه بها.\nguid\nالقرآن حق من الله، وما نزل به كله حق.\nالقراءة المتأنية تعين على تدبر القرآن.\nمن مراحل الترقي بالقرآن الكريم: التلاوة المتأنية، ثم التدبر، ثم السجود والدعاء، ثم الخشية والبكاء.\nrefl\nوَقُرۡءَانٗا فَرَقۡنَٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثٖ\nأي: على مهل؛ ليتدبروه، ويتفكروا في معانيه، ويستخرجوا علومه. السعدي:٤٦٨.\nما الطريقة الأمثل لقراءة القرآن لمن أراد أن يتدبره؟\nقُلۡ ءَامِنُواْ بِهِۦٓ أَوۡ لَا تُؤۡمِنُوٓاْۚ إِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مِن قَبۡلِهِۦٓ إِذَا يُتۡلَىٰ عَلَيۡهِمۡ يَخِرُّونَۤ لِلۡأَذۡقَانِۤ سُجَّدٗاۤ ١٠٧\n﴿قُلۡ ءَامِنُواْ بِهِۦٓ أَوۡ لَا تُؤۡمِنُوٓاْۚ﴾: أمر باحتقارهم، وعدم الاكتراث بهم؛ كأنه يقول: سواء آمنتم أو لم تؤمنوا، لكونكم لستم بحجة، وإنَّما الحجة أهل العلم من قبله، وهم المؤمنون من أهل الكتاب. ﴿إِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مِن قَبۡلِهِۦٓ﴾: يعني المؤمنين من أهل الكتاب، وقيل: الذين كانوا على الحنيفية قبل البعثة. ابن جزي:١/٤٩٩.\nفي هذه الآية رفعة لشأن أهل العلم، وضح ذلك.\nإِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مِن قَبۡلِهِۦٓ إِذَا يُتۡلَىٰ عَلَيۡهِمۡ يَخِرُّونَۤ لِلۡأَذۡقَانِۤ سُجَّدٗاۤ ١٠٧ وَيَقُولُونَ سُبۡحَٰنَ رَبِّنَآ إِن كَانَ وَعۡدُ رَبِّنَا لَمَفۡعُولٗا ١٠٨ وَيَخِرُّونَ لِلۡأَذۡقَانِ يَبۡكُونَ وَيَزِيدُهُمۡ خُشُوعٗا۩ ١٠٩\n﴿وَيَخِرُّونَ لِلۡأَذۡقَانِ يَبۡكُونَ﴾: هذه مبالغة في صفتهم، ومدح لهم. وحُق لكل من توسم بالعلم وحصَّل منه شيئًا أن يجري إلى هذه المرتبة؛ فيخشع عند استماع القرآن، ويتواضع ويذل. وفى مسند الدارمي أبى محمد عن التيمي قال: \"من أوتي من العلم ما لم يُبكه لخليق ألا يكون أوتى علمًا؛ لأن الله تعالى نعت العلماء\"... ثم تلا هذه الآية. القرطبي:١٣/١٨٩.\nبيّن ما ينبغي أن يكون عليه حال أهل العلم عند سماعهم القرآن.\nوَيَخِرُّونَ لِلۡأَذۡقَانِ يَبۡكُونَ وَيَزِيدُهُمۡ خُشُوعٗا۩ ١٠٩\nالخرور على الذقن عبادة مقصودة يحبها الله، وليس المراد بالخرور إلصاق الذقن بالأرض كما تلصق الجبهة. والخرور على الذقن هو مبدأ الركوع، والسجود منتهاه. ابن تيمية:٤/٢٤٩.\nما صورة الخرور على الذقن التي يحبها الله؟\nٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَنزَلَ عَلَىٰ عَبۡدِهِ ٱلۡكِتَٰبَ\nفحمد نفسه، وفي ضمنه إرشاد العباد ليحمدوه على إرسال الرسول إليهم، وإنزال الكتاب عليهم. السعدي:٤٦٩.\nما الفائدة العملية التي يفيدها المسلم من معرفة حمد الله لنفسه؟\nٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَنزَلَ عَلَىٰ عَبۡدِهِ ٱلۡكِتَٰبَ وَلَمۡ يَجۡعَل لَّهُۥ عِوَجَاۜ ١\nوخص رسوله بالذكر؛ لأن إنزال القرآن عليه كان نعمة عليه على الخصوص، وعلى سائر الناس على العموم. البغوي:٣/٥.\nلم خص النبي -صلى الله عليه وسلم- بالذكر؟\nقَيِّمٗا لِّيُنذِرَ بَأۡسٗا شَدِيدٗا مِّن لَّدُنۡهُ وَيُبَشِّرَ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرًا حَسَنٗا ٢ مَّٰكِثِينَ فِيهِ أَبَدٗا ٣\nهذا القرآن قد اشتمل على كل عمل صالح موصل لما تستبشر به النفوس وتفرح به الأرواح. السعدي:٤٧٠.\nما مصدر الاستبشار عند المؤمن؟"],[294,"§الكهف\nwords\nبَاخِعٌمُهلِكٌ.\nأَسَفًاحَزَنًا، وَغَمًّا.\nوَالرَّقِيمِاللَّوحِ الَّذِي كُتِبَت فِيهِ أَسمَاؤُهُم.\nأَمَدًامُدَّةً، وَغَايَةً.\nشَطَطًاجَائِرًا، بَعِيدًا عَنِ الحَقِّ.\ndeeds\nقل: \"اللهم يا مقلب القلوب ثبت قلبي على دينك\".\nأكثر اليوم من هذا الدعاء.\nخطط اليوم لاكتساب رفقة صالحة تعينك على العبادة والثبات على الدين.\nguid\nشدة شفقة النبي -صلى الله عليه وسلم- على الناس ليؤمنوا؛ حتى يكاد أن يهلك نفسه لذلك.\nاحذر! فالنِّعَمُ والملذات الدنيوية إنَّما هي ابتلاءٌ من الله -سبحانه وتعالى-؛ لأنك تستطيع أن تستعين بها على الطاعة، وتستطيع أن تستعين بها على المعصية.\nالرفقة الصالحة من أسباب الهداية والثبات على الدين.\nrefl\nفَلَعَلَّكَ بَٰخِعٞ نَّفۡسَكَ عَلَىٰٓ ءَاثَٰرِهِمۡ إِن لَّمۡ يُؤۡمِنُواْ بِهَٰذَا ٱلۡحَدِيثِ أَسَفًا ٦\nفي هذه الآية ونحوها عبرة؛ فإن المأمور بدعاء الخلق إلى الله عليه التبليغ والسعي بكل سبب يوصل إلى الهداية، وسدِّ طرق الضلال والغواية بغاية ما يمكنه، مع التوكل على الله في ذلك؛ فإن اهتدوا فبها ونِعمَت، وإلا فلا يحزن ولا يأسف؛ فإن ذلك مُضعِفٌ للنفس، هادم للقوى، ليس فيه فائدة؛ بل يمضي على فعله الذي كُلِّفَ به وتوجه إليه، وما عدا ذلك فهو خارج عن قدرته. السعدي:٤٧٠.\nفي الآية فائدة دعوية جليلة، بَيِّنها.\nإِنَّا جَعَلۡنَا مَا عَلَى ٱلۡأَرۡضِ زِينَةٗ لَّهَا لِنَبۡلُوَهُمۡ أَيُّهُمۡ أَحۡسَنُ عَمَلٗا ٧\n﴿إِنَّا جَعَلۡنَا مَا عَلَى ٱلۡأَرۡضِ زِينَةً لَّهَا﴾ يعني: ما يصلح للتزين؛ كالملابس، والمطاعم، والأشجار، والأنهار، وغير ذلك. ﴿لِنَبۡلُوَهُمۡ أَيُّهُمۡ أَحۡسَنُ عَمَلًا﴾ أي: لنختبرهم أيهم أزهد في زينة الدنيا. ابن جزي:١/٥٠٢.\nزيّن الله الأرض بأنواع الزينة لحكمة عظيمة، فما هي؟\nأَمۡ حَسِبۡتَ أَنَّ أَصۡحَٰبَ ٱلۡكَهۡفِ وَٱلرَّقِيمِ كَانُواْ مِنۡ ءَايَٰتِنَا عَجَبًا ٩ إِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا ١٠\nوفيه لفت لعقول السائلين عن الاشتغال بعجائب القصص إلى أن الأولى لهم الاتعاظ بما فيها من العِبر والأسباب وآثارها، ولذلك ابتُدئ ذكرُ أحوالهم بقوله: ﴿إِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةً وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدًا﴾. ابن عاشور:١٥/٢٥٩.\nينبغي الاشتغال بما في القصص من عبر وعظات عما فيها من عجائب؛ دلِّل على ذلك من خلال عرض قصة أصحاب الكهف.\nإِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا ١٠\nهذه الآية صريحة في الفرار بالدين وهجرة الأهل والبنين، والقرابات، والأصدقاء، والأوطان، والأموال؛ خوف الفتنة وما يلقاه الإنسان من المحنة، وقد خرج النبي -صلى الله عليه وسلم- فارًّا بدينه، وكذلك أصحابه... وهجروا أوطانهم، وتركوا أرضهم، وديارهم، وأهاليهم، وأولادهم، وقراباتهم، وإخوانهم؛ رجاء السلامة بالدين والنجاة من فتنة الكافرين. القرطبي:١٣/٢١٦.\nهل يترك المؤمن موطنه إذا خشي على دينه؟ أم يغامر بدينه ليبقى في موطنه؟\nإِنَّهُمۡ فِتۡيَةٌ ءَامَنُواْ بِرَبِّهِمۡ وَزِدۡنَٰهُمۡ هُدٗى ١٣\nذكر تعالى أنهم فتية، وهم الشباب؛ وهم أقبل للحق، وأهدى للسبيل من الشيوخ الذين قد عتوا وانغمسوا في دين الباطل، ولهذا كان أكثر المستجيبين لله تعالى ولرسوله -صلى الله عليه وسلم- شبابًا. وأمَّا المشايخ من قريش فعامتهم بقوا على دينهم، ولم يُسلِم منهم إلا القليل. ابن كثير:٣/٧٢.\nأي فئات العمر أقرب لقبول دعوة الحق؟\nوَرَبَطۡنَا عَلَىٰ قُلُوبِهِمۡ\nبالصبر والتثبيت، وقويناهم بنور الإيمان؛ حتى صبروا على هجران دار قومهم، ومفارقة ما كانوا فيه من العز، وخصب العيش، وفروا بدينهم إلى الكهف. البغوي:٣/١٧.\nكيف ربط الله -تعالى- على قلوب أصحاب الكهف؟\nوَرَبَطۡنَا عَلَىٰ قُلُوبِهِمۡ\nالربط على القلب عكس الخذلان؛ فالخذلان: حلُّه من رباط التوفيق؛ فيغفل عن ذكر ربه ويتبع هواه، ويصير أمره فرطًا. والربط على القلب: شدُّه برباط التوفيق؛ فيتصل بذكر ربه، ويتبع مرضاته، ويجتمع عليه شمله. ابن القيم:٢/١٥٧.\nبيّن من خلال الوقفة الفرق بين الربط على القلب والخذلان."],[295,"§الكهف\nwords\nمِرفَقًامَا تَنتَفِعُونَ بِهِ فِي حَيَاتِكُم مِن أَسبَابِ العَيشِ.\nتَزَاوَرُتَمِيلُ.\nتَقرِضُهُمتَترُكُهُم، وَتَتَجَاوَزُ عَنهُم.\nفَجوَةٍمُتَّسَعٍ.\ndeeds\nرتّب لنفسك قائمة طعام تعتمد على الأزكى والأطيب من الأطعمة، وابتعد عن المحرم والمشتبه فيه؛ فإن هذا أصلح لقلبك، وأقوى لعقلك، وأحرى لاستجابة دعائك.\nلا سبيل إلى نيل الهداية إلا من الله؛ فاسألها ممن يملكها، واستعذ به من الضلال والغواية.\nلا تتمنَّ لقـاء العـدو، واسـأل الله تعـالى المعـافـاة في دينـك ودنيـاك.\nguid\nحفظ الله أولياءه في نومهم أفلا يحفظهم في يقظتهم.\nطيب الطعام له منافع كثيرة؛ فهو سبب للهداية، وإجابة الدعاء، والبعد عن الأمراض.\nكلما كان المؤمن على حذر من عداوة الكفار؛ كان في مأمن من شرهم.\nrefl\nوَإِذِ ٱعۡتَزَلۡتُمُوهُمۡ وَمَا يَعۡبُدُونَ إِلَّا ٱللَّهَ\nفيقال: إن ملكهم لمَّا دعوه إلى الإيمان بالله أبى عليهم وتهددهم وتوعدهم... وأجّلهم لينظروا في أمرهم لعلهم يرجعون عن دينهم الذي كانوا عليه... فإنهم في تلك النظِرة توصلوا إلى الهرب منه والفرار بدينهم من الفتنة...؛ ففي هذه الحال تشرع العزلة عن الناس، ولا تشرع فيما عداها لما يفوت بها من ترك الجماعات والجُمَع. ابن كثير:٣/٧٣.\nمتى يُشرَعُ للمسلم أن يعتزل الناس ويفر بدينه؟\nوَتَرَى ٱلشَّمۡسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهۡفِهِمۡ ذَاتَ ٱلۡيَمِينِ وَإِذَا غَرَبَت تَّقۡرِضُهُمۡ ذَاتَ ٱلشِّمَالِ وَهُمۡ فِي فَجۡوَةٖ مِّنۡهُۚ ذَٰلِكَ مِنۡ ءَايَٰتِ ٱللَّهِۗ\nومعنى الآية: أن الشمس لا تصيبهم عند طلوعها، ولا عند غروبها؛ لئلَّا يحترقوا بحرها، فقيل: إن ذلك كرامة لهم وخرقُ عادةٍ. ابن جزي:١/٥٠٤.\nكيف حفظ الله أهل الكهف؟\nمَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ\nأي: لا سبيل إلى نيل الهداية إلا من الله؛ فهو الهادي، المرشد لمصالح الدارين. السعدي:٤٧٢.\nإذا أردت الهداية فمِمَّن تطلبها وتسألها؟\nوَنُقَلِّبُهُمۡ ذَاتَ ٱلۡيَمِينِ وَذَاتَ ٱلشِّمَالِۖ\nهذا أيضًا من حفظه لأبدانهم؛ لأن الأرض من طبيعتها أكل الأجسام المتصلة بها، فكان من قَدَر الله أن قَلَّبَهم على جنوبهم يمينًا وشمالًا بقدر ما لا تفسد الأرض أجسامهم، والله تعالى قادر على حفظهم من الأرض من غير تقليب، ولكنه تعالى حكيم، أراد أن تجري سنته في الكون، ويربط الأسباب بمسبباتها. السعدي:٤٧٢.\nالله تعالى قادر على حفظ أهل الكهف من الأرض من غير تقليب، فلماذا جعلهم يتقلبون؟\nوَكَلۡبُهُم بَٰسِطٞ ذِرَاعَيۡهِ بِٱلۡوَصِيدِۚ\nقال ابن عطية: \"قلت: إذ كان بعض الكلاب قد نال هذه الدرجة العليا بصحبته ومخالطته الصلحاء والأولياء حتى أخبر الله تعالى بذلك في كتابه -جل وعلا-، فما ظنك بالمؤمنين الموحدين المخالطين المحبين للأولياء والصالحين\". القرطبي:١٣/٢٣٢.\nماذا نتعلم من ذكر القرآن للكلب في هذه القصة؟\nقَالُواْ رَبُّكُمۡ أَعۡلَمُ بِمَا لَبِثۡتُمۡ\nالأدب فيمن اشتبه عليه العلم أن يرده إلى عالمه، وأن يقف عند حده. السعدي:٤٧٣.\nما الأدب الشرعي إذا سُئلت عن أمر لا تعلمه؟\nفَلۡيَنظُرۡ أَيُّهَآ أَزۡكَىٰ طَعَامٗا فَلۡيَأۡتِكُم بِرِزۡقٖ مِّنۡهُ\nجواز أكل الطيبات والمطاعم اللذيذة إذا لم تخرج إلى حد الإسراف المنهي عنه، وخصوصًا إذا كان الإنسان لا يلائمه إلا ذلك. السعدي:٤٧٣.\nهل الإنسان مأمورٌ بأن يبتعد عن الأزكى من الطعام؟"],[296,"§الكهف\nwords\nأَعثَرنَا عَلَيهِمأَطلَعنَا عَلَيهِم أَهلَ ذَلِكَ الزَّمَانِ.\nلا رَيبَلا شَكَّ.\nغَلَبُوا عَلَى أَمرِهِمأَصحَابُ النُّفُوذِ فِيهِم.\nرَجمًا بِالغَيبِقَولًا بِالظَّنِّ مِن غَيرِ دَلِيلٍ.\nفَلاَ تُمَارِ فِيهِملاَ تُجَادِل فِي عِدَّتِهِم.\nإلَّا مِرَاءً ظَاهِرًاإلَّا جِدَالًا ظَاهِرًا لاَ عُمقَ فِيهِ بِأَن تَتلُوَ مَا أُوحِيَ إِلَيكَ.\nمُلتَحَدًامَلجَأً تَلجَأُ إِلَيهِ.\ndeeds\nأكثر اليوم من ذكر الله تعالى.\nاحرص من اليوم عند كلِّ قولٍ مرتبطٍ بأفعال مستقبلية أن تقَيِّدهُ بقولك: \"إن شاء الله تعالى\".\nاتل سورة من القرآن الكريم.\nguid\nالعاطفة والحماس في عمل الخير لا يكفيان؛ فلا بد من التقيد بأحكام الشرع؛ فبناء المساجد على القبور محرم.\nلا تجادل إلا فيما عندك فيه علم.\nإذا أردتَ أن تستفتي في شؤون دينك فابحث عن الأصلح في عبادته وعلمه.\nrefl\nوَكَذَٰلِكَ أَعۡثَرۡنَا عَلَيۡهِمۡ لِيَعۡلَمُوٓاْ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَأَنَّ ٱلسَّاعَةَ لَا رَيۡبَ فِيهَآ\nفي هذه القصة دليل على أن من فرَّ بدينه من الفتن سلَّمه الله منها، وأن من حرص على العافية عافاه الله، ومن أوى إلى الله آواه الله وجعله هدايةً لغيره، ومن تحمَّل الذلَّ في سبيله وابتغاء مرضاته كان آخِرُ أمره وعاقبته العزّ العظيم من حيث لا يحتسب. السعدي:٤٧٣.\nاذكر ثلاث فوائد مختصرة من قصة أصحاب الكهف.\nفَقَالُواْ ٱبۡنُواْ عَلَيۡهِم بُنۡيَٰنٗاۖ رَّبُّهُمۡ أَعۡلَمُ بِهِمۡۚ قَالَ ٱلَّذِينَ غَلَبُواْ عَلَىٰٓ أَمۡرِهِمۡ لَنَتَّخِذَنَّ عَلَيۡهِم مَّسۡجِدٗا ٢١\nواتخاذ المساجد على القبور، والصلاة فيها منهي عنه؛ لأن ذلك ذريعة إلى عبادة صاحب القبر، أو شبيهٌ بفعل من يعبدون صالحي ملتهم. ابن عاشور:١٥/٢٩٠.\nلماذا نهينا عن اتخاذ المساجد على القبور؟\nقُل رَّبِّيٓ أَعۡلَمُ بِعِدَّتِهِم\nإرشاد إلى أن الأحسن في مثل هذا المقام رد العلم إلى الله تعالى؛ إذ لا احتياج إلى الخوض في مثل ذلك بلا علم، لكن إذا اطَّلعنا على أمر قلنا به، وإلا وقَفنا. ابن كثير:٣/٧٧.\nما الطريقة المثلى لطالب العلم عند تحيره وتوقفه في بعض المسائل العلمية؟\nوَلَا تَسۡتَفۡتِ فِيهِم مِّنۡهُمۡ أَحَدٗا ٢٢\nفيها دليل على المنع من استفتاء من لا يصلح للفتوى؛ إما لقصوره في الأمر المستفتى فيه، أو لكونه لا يبالي بما تكلَّم به، وليس عنده ورع يحجزه... وفي الآية أيضًا دليل على أن الشخص قد يكون منهيًا عن استفتائه في شيء دون آخر؛ فيُستفتى فيما هو أهل له، بخلاف غيره؛ لأن الله لم ينه عن استفتائهم مطلقًا، إنَّما نهى عن استفتائهم في قصة أصحاب الكهف، وما أشبهها. السعدي:٤٧٤.\nاذكر بعض المسائل المتعلقة بالفتوى، والمستنبطة من الآية.\nوَلَا تَقُولَنَّ لِشَاْيۡءٍ إِنِّي فَاعِلٞ ذَٰلِكَ غَدًا ٢٣ إِلَّا أَن يَشَآءَ ٱللَّهُۚ\nيعني: إذا عزمت على أن تفعل غدًا شيئًا فلا تقل: أفعل غدًا، حتى تقول: إن شاء الله. البغوي:٣/٢٣.\nبيّن الأدب القرآني فيما يجب على العبد أن يقول إذا أراد فعل الشيء في المستقبل.\nوَٱذۡكُر رَّبَّكَ إِذَا نَسِيتَ\nأرشد من نسي الشيء في كلامه إلى ذكر الله تعالى؛ لأن النسيان منشأه من الشيطان... وذكر الله تعالى يطرد الشيطان، فإذا ذهب الشيطان ذهب النسيان؛ فذكر الله سبب للذكر. ابن كثير:٣/٧٨.\nما العلاقة بين ذكر الله وذهاب النسيان؟\nمَا لَهُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا يُشۡرِكُ فِي حُكۡمِهِۦٓ أَحَدٗا ٢٦\nالولي: هو من انعقد بينك وبينه سبب يواليك وتواليه به؛ فالإيمان سبب يوالي به المؤمنون ربهم بالطاعة، ويواليهم به الثوابَ والنصر والإعانة. الشنقيطي:٣/٢٥٧.\nكيف تكون ولاية الله سبحانه للمؤمنين، وولاية المؤمنين لله؟"],[297,"§الكهف\nwords\nفُرُطًاهَلاَكًا، وَضَيَاعًا.\nسُرَادِقُهَاسُورُهَا.\nكَالمُهلِكَالزَّيتِ العَكِرِ.\nوَسَاءَت مُرتَفَقًاقَبُحَت مَنزِلًا وَمَقَامًا.\nسُندُسٍرَقِيقِ الحَرِيرِ.\nوَإِستَبرَقٍغَلِيظِ الحَرِيرِ.\ndeeds\nشارك في برنامج دعوي مع مجموعة من الصالحين.\nابحث عن رجل من الأخيار وصاحبه، واصبر نفسك على مصاحبته واحتسبها عبادة لله سبحانه.\nاستعذ بالله من أن تتكبر بسبب ما وهبك الله من النعم، واسأل الله أن يجعلها عونًا لك على عبادته.\nguid\nاجعل لك وردًا تحرص عليه في أذكار الصباح والمساء.\nعليك بصحبة الأخيار، ومجاهدة النفس على صحبتهم ومخالطتهم؛ وإن كانوا فقراء، واحذر أن تلهيك الدنيا عن ذلك.\nمن أعظم العقوبات أن تُعَاقَبَ على بعض المعاصي بأن يُجعل قلبُك غافلًا عن ذكر الله تعالى.\nrefl\nوَٱصۡبِرۡ نَفۡسَكَ مَعَ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ وَلَا تَعۡدُ عَيۡنَاكَ عَنۡهُمۡ تُرِيدُ زِينَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُۥ عَن ذِكۡرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمۡرُهُۥ فُرُطٗا ٢٨\n﴿وَٱصۡبِرۡ نَفۡسَكَ﴾ أي: احبسها صابرًا ﴿مَعَ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم﴾: هم فقراء المسلمين كبلال وخباب وصهيب. وكان الكفار قد قالوا له: اطرد هؤلاء نجالسك نحن. ابن جزي:١/٥٠٧.\nيتعامل الداعية في دعوته مع مختلف الطبقات؛ فما المنهج القرآني في التعامل معهم؟\nوَٱصۡبِرۡ نَفۡسَكَ مَعَ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ\nفي الآية استحباب الذكر والعبادة والدعاء طرفي النهار؛ لأن الله مدحهم بفعله، وكل فعل مدح الله فاعله دلَّ ذلك على أن الله يحبه، وإذا كان يحبه فإنه يأمر به، ويُرَغِّبُ فيه. السعدي:٤٧٥.\nكيف تستدل بالآية على مشروعية أذكار الصباح والمساء؟\nوَلَا تَعۡدُ عَيۡنَاكَ عَنۡهُمۡ تُرِيدُ زِينَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ\n(تريد زينة الحياة الدنيا): فإن هذا ضار غير نافع، قاطع عن المصالح الدينية؛ فإن ذلك يوجب تعلق القلب بالدنيا، فتصير الأفكار والهواجس فيها، وتزول من القلب الرغبة في الآخرة؛ فإن زينة الدنيا تروق للناظر، وتسحر العقل؛ فيغفل القلب عن ذكر الله، ويُقبِل على اللذات والشهوات، فيضيع وقته، وينفرط أمره. السعدي:٤٧٥.\nما ضرر محبة الدنيا على الآخرة؟\nوَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُۥ عَن ذِكۡرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمۡرُهُۥ فُرُطٗا ٢٨\nودلت الآية على أن الذي ينبغي أن يُطاع ويكون إمامًا للناس من امتلأ قلبه بمحبة الله، وفاض ذلك على لسانه؛ فلهج بذكر الله، واتبع مراضيَ ربه؛ فقدمها على هواه؛ فحفظ بذلك ما حفظ من وقته، وصلحت أحواله، واستقامت أفعاله، ودعا الناس إلى ما مَنَّ الله به عليه؛ فحقيق بذلك أن يتبع ويجعل إمامًا. السعدي:٤٧٥.\nلا بُدَّ للإنسان أن يُقَلِّدَ غيره ويتبعه في بعض الأمور الدينية، أو في الأمور الدنيوية؛ فمن الذي يجب علينا اتباعه؟ ومن الذي يجب علينا مفارقته؟\nوَقُلِ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَن شَآءَ فَلۡيُؤۡمِن وَمَن شَآءَ فَلۡيَكۡفُرۡۚ\nالله يؤتي الحق من يشاء وإن كان ضعيفًا، ويحرمه من يشاء وإن كان قويًّا غنيًّا، ولست بطارد المؤمنين لهواكم؛ فإن شئتم فآمنوا، وإن شئتم فاكفروا. القرطبي ١٣/٢٦٠.\nعطايا الآخرة والحرمان منها هل يعودان إلى غنى الإنسان وفقره؟\nوَقُلِ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَن شَآءَ فَلۡيُؤۡمِن وَمَن شَآءَ فَلۡيَكۡفُرۡۚ\nوقدم الإيمان على الكفر؛ لأن إيمانهم مرغوب فيه. ابن عاشور:١٥/٣٠٧.\nلماذا قدم الإيمان على الكفر في هذه الآية ؟\nوَكَانَ لَهُۥ ثَمَرٞ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكۡثَرُ مِنكَ مَالٗا وَأَعَزُّ نَفَرٗا ٣٤\nقال قتادة: \"تلك والله أمنية الفاجر: كثرة المال، وعزة النفر\". ابن كثير:٣/٨١.\nما غاية أمنية الكافر؟ وما الذي يفيده المسلم من هذا؟"],[298,"§الكهف\nwords\nتَبِيدَتَهلِكَ.\nصَعِيدًا زَلَقًاأَرضًا مَلسَاءَ جَردَاءَ لاَ تَثبُتُ عَلَيهَا قَدَمٌ، وَلاَ تُنبِتُ شَيئًا.\nغَورًاغَائِرًا ذَاهِبًا فِي عُمقِ الأَرضِ.\ndeeds\nانصح أحد أصحابك المخالفين لأمر الله ورسوله؛ فالصحبة لا تعني عدم التناصح.\nتأمل إنجازات حققتها في حياتك، وانسب الفضل فيها إلى الله تعالى، وقل: \"ما شاء الله، لا قوة إلاّ بالله\".\nاستغفر الله من نعمة نسبتها إلى نفسك ونسيت فيها فضل الله عليك؛ فإن عقوبة الله قريبة من الغافل عن شكره.\nguid\nاحذر الغرور والأمن من مكر الله تعالى.\nمن خذله الله تعالى فإنه لا يُنصر أبدًا.\nتواضع لعباد الله، وإياك والعلو والكبر.\nrefl\nوَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمٞ لِّنَفۡسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ أَبَدٗا ٣٥\n﴿وَهُوَ ظَالِمٌ لِّنَفۡسِهِۦ﴾: إما بكفره، وإما بمقابلته لأخيه؛ فإنها تتضمن الفخر، والكبر، والاحتقار لأخيه. ابن جزي:١/٥١٠.\nظلم صاحب الجنتين نفسه بأمور أربعة، عددها؟\nوَلَئِن رُّدِدتُّ إِلَىٰ رَبِّي لَأَجِدَنَّ خَيۡرٗا مِّنۡهَا مُنقَلَبٗا ٣٦\nفأيُّ تلازم بين عطاء الدنيا وعطاء الآخرة حتى يظن بجهله أن من أُعطِيَ في الدنيا أُعطِيَ في الآخرة، بل الغالب أن الله تعالى يَزوِي الدنيا عن أوليائه وأصفيائه، ويوسعها على أعدائه الذين ليس لهم في الآخرة نصيب. السعدي:٤٧٧.\nهل هناك تلازم بين عطاء الدنيا وعطاء الآخرة؟\nوَلَوۡلَآ إِذۡ دَخَلۡتَ جَنَّتَكَ قُلۡتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِۚ\nأي: ما اجتمع لك من المال فهو بقدرة الله تعالى وقوته، لا بقدرتك وقوتك، ولو شاء لنزع البركة منه فلم يجتمع. القرطبي:١٣/٢٨٠.\nهل يملك الإنسان شيئًا بقدرته وقوته؟\nإِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالٗا وَوَلَدٗا ٣٩ فَعَسَىٰ رَبِّيٓ أَن يُؤۡتِيَنِ خَيۡرٗا مِّن جَنَّتِكَ\nأخبره أن نعمة الله عليه بالإيمان والإسلام -ولو مع قلة ماله وولده- أنها هي النعمة الحقيقية، وأن ما عداها مُعَرَّضٌ للزوال، والعقوبة عليه والنكال. السعدي:٤٧٧.\nما أفضل النعم وأكملها وأتمها على المسلم؟\nوَأُحِيطَ بِثَمَرِهِۦ فَأَصۡبَحَ يُقَلِّبُ كَفَّيۡهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا\nوأحاط به هذا العقاب لا لمجرد الكفر؛ لأن الله قد يمتّع كافرين كثيرين طول حياتهم، ويملي لهم، ويستدرجهم، وإنَّما أحاط به هذا العقاب جزاءً على طغيانه، وجعله ثروته وماله وسيلة إلى احتقار المؤمن الفقير. ابن عاشور:١٥/٣٢٨.\nما سبب تعجيل العقوبة لهذا الكافر المذكور في الآية مع أن الله تعالى قد يمتع كافرين كثيرين طول حياتهم؟\nوَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُشۡرِكۡ بِرَبِّيٓ أَحَدٗا ٤٢\nولا يستبعد من رحمة الله ولطفه أن صاحب هذه الجنة التي أحيط بها تحسنت حاله، ورزقه الله الإنابة إليه، وراجع رشده، وذهب تمرده وطغيانه؛ بدليل أنه أظهر الندم على شركه بربه، وأن الله أذهب عنه ما يطغيه، وعاقبه في الدنيا، وإذا أراد الله بعبد خيرًا عجل له العقوبة في الدنيا. السعدي:٤٧٨.\nقد تكون العقوبة التي أصابت صاحب الجنتين خيرًا له، بَيِّن وجه ذلك.\nوَٱضۡرِبۡ لَهُم مَّثَلَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ فَأَصۡبَحَ هَشِيمٗا تَذۡرُوهُ ٱلرِّيَٰحُۗ\nقالت الحكماء: إنَّما شبه تعالى الدنيا بالماء... لأن الماء لا يستقيم على حالة واحدة؛ كذلك الدنيا. ولأن الماء لا يبقى ويذهب؛ كذلك الدنيا تفنى. ولأن الماء لا يقدر أحد أن يدخله ولا يبتل؛ كذلك الدنيا: لا يسلم أحد دخلها من فتنتها وآفتها. ولأن الماء إذا كان بقدر كان نافعًا منبتًا، وإذا جاوز المقدار كان ضارًّا مهلكًا؛ وكذلك الدنيا: الكفاف منها ينفع، وفضولها يضر. القرطبي:١٣/٢٨٩.\nبيّن بعض أوجه الشبه بين الدنيا والماء."],[299,"§الكهف\nwords\nوَخَيرٌ أَمَلًاخَيرُ مَا يُرجَى عِندَ اللهِ.\nفَفَسَقَفَخَرَجَ.\nعَضُدًاأَعوَانًا.\nمَوبِقًامَهلِكًا فِي جَهَنَّمَ يَهلِكُونَ فِيهِ جَمِيعًا.\ndeeds\nسل الله تعالى سلامة الصدر، واستعذ بالله من الحسد والكبر؛ فإنما أهلَكَ الشيطان داءُ الحسد والكبر.\nحدد ذنوبًا فعلتها تراها من الكبائر، وأكثر من الاستغفار منها؛ لعلها تمسح من صحيفة سيئاتك.\nحدد عملًا صالحًا كبيرًا ليكون مشروع حياتك، ثم ابدأ خطوات جادة في تحقيقه، واستعن بالله سبحانه عليه حتى لا تعيش غافلًا.\nguid\nلا تجعل المال والبنين مشغلة لك عن عمل الصالحات، بل اجعلها مساعدة لك عليه.\nمن أحصى على نفسه في الدنيا الحسنات والسيئات لم يتفاجأ يوم القيامة بكتابه.\nأشد الندم حينما يكتشف المشرك يوم القيامة أن لا أحد يشارك الله سبحانه في تفريج الكربة وإجابة الدعاء.\nrefl\nٱلۡمَالُ وَٱلۡبَنُونَ زِينَةُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ\n﴿ٱلۡمَالُ وَٱلۡبَنُونَ﴾: التي يفتخر بها عتبة وأصحابه الأغنياء (زينة الحياة الدنيا): ليست من زاد الآخرة. قال علي بن أبي طالب -رضي الله عنه-: «المال والبنون حرث الدنيا، والأعمال الصالحة حرث الآخرة، وقد يجمعها الله لأقوام». البغوي:٣/٣٤.\nما حرث الدنيا، وما حرث الآخرة؟\nوَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٌ أَمَلٗا ٤٦\nالذي يبقى للإنسان وينفعه ويسره: الباقيات الصالحات؛ وهذا يشمل جميع الطاعات الواجبة والمستحبة من حقوق الله وحقوق عباده؛ من: صلاة، وزكاة، وصدقة، وحج، وعمرة، وتسبيح، وتحميد، وتهليل، وتكبير، وقراءة، وطلب علم نافع، وأمر بمعروف، ونهي عن منكر، وصلة رحم، وبر والدين، وقيام بحق الزوجات، والمماليك، والبهائم، وجميع وجوه الإحسان إلى الخلق. السعدي:٤٧٩.\nاذكر بعض الباقيات الصالحات.\nوَتَرَى ٱلۡأَرۡضَ بَارِزَةٗ\nأي: بادية ظاهرة، ليس فيها مَعلَمٌ لأحد، ولا مكان يواري أحدًا، بل الخلق كلهم ضاحون لربهم، لا تخفى عليه منهم خافية. ابن كثير:٣/٨٥-٨٦.\nما التهديد الكامِنُ في قوله تعالى: ﴿وَتَرَى ٱلۡأَرۡضَ بَارِزَةً﴾؟\nوَعُرِضُواْ عَلَىٰ رَبِّكَ صَفّٗا لَّقَدۡ جِئۡتُمُونَا كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةِۚ\nأي: بلا مال، ولا أهل، ولا عشيرة؛ ما معهم إلا الأعمال التي عملوها، والمكاسب في الخير والشر التي كسبوها. السعدي:٤٧٩.\nما المقصود بقوله تعالى: ﴿لَّقَدۡ جِئۡتُمُونَا كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةِۭۚ﴾؟\nوَيَقُولُونَ يَٰوَيۡلَتَنَا مَالِ هَٰذَا ٱلۡكِتَٰبِ لَا يُغَادِرُ صَغِيرَةٗ وَلَا كَبِيرَةً إِلَّآ أَحۡصَىٰهَاۚ وَوَجَدُواْ مَا عَمِلُواْ حَاضِرٗاۗ وَلَا يَظۡلِمُ رَبُّكَ أَحَدٗا ٤٩\nقال قتادة: \"اشتكى القوم الإحصاء، وما اشتكى أحد ظلمًا، فإياكم ومحقرات الذنوب؛ فإنها تجتمع على صاحبها حتى تهلكه\". القرطبي:١٥/٤٥٩.\nمتى يهلك العبد بالصغائر؟\nوَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ\nسجود تشريف، وتكريم، وتعظيم. ابن كثير:٣/٨٧.\nهل سجود الملائكة لآدم كان سجود عبادة؟ أم ماذا؟\nوَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ كَانَ مِنَ ٱلۡجِنِّ فَفَسَقَ عَنۡ أَمۡرِ رَبِّهِۦٓۗ أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوۡلِيَآءَ مِن دُونِي وَهُمۡ لَكُمۡ عَدُوُّۢۚ بِئۡسَ لِلظَّٰلِمِينَ بَدَلٗا ٥٠\nيقول تعالى منبهًا بني آدم على عداوة إبليس لهم، ولأبيهم من قبلهم، ومُقَرِّعًا لمن اتبعه منهم، وخالف خالقه ومولاه، وهو الذي أنشأه وابتدأه بألطافه، ورزقه وغذاه، ثم بعد هذا كله والى إبليس وعادى الله، فقال تعالى: ﴿وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ﴾. ابن كثير:٣/٨٧.\nبيّن جهل بعض بني آدم وعنادهم من خلال الآية."],[300,"§الكهف\nwords\nلِيُدحِضُوالِيُزِيلُوا.\nأَكِنَّةًأَغطِيَةً.\nوَقرًاصَمَمًا وَثِقَلًا فِي السَّمعِ.\nمَوئِلًامَلجَأً، وَمَخلَصًا.\nحُقُبًازَمَنًا طَوِيلًا.\ndeeds\nاقرأ قصة من القصص الواردة في سورة الكهف، وتدبر ما فيها من العبر والعظات.\nحدد واحدًا من أسباب غفلتك، وابدأ خطوات جادة في تركه، واسأل الله أن يعوضك خيرًا منه.\nزر عالمًا، واستمع منه العلم، أو اقرأ عليه كتابًا، أو تعلم من أدبه وسمته؛ فذاك من الباقيات الصالحات.\nguid\nالجدل والمخاصمة غريزة في الإنسان؛ فليحرص على تهذيبها وتوجيهها في الخير.\nاستخدم الترغيب والترهيب في دعوتك إلى الله تعالى.\nقد يضرب الله سبحانه الأكنة والغشاوة على قلب العاصي، فلا يستطيع تدبر القرآن وفهم أمثاله وقصصه حتى يتوب.\nrefl\nوَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِلنَّاسِ مِن كُلِّ مَثَلٖۚ وَكَانَ ٱلۡإِنسَٰنُ أَكۡثَرَ شَيۡءٖ جَدَلٗا ٥٤\nعن علي: أن النبي -صلى الله عليه وسلم- طرقه وفاطمةَ ليلًا؛ فقال: «ألا تصليان؟!» فقال علي: يا رسول الله، إنَّما أنفسنا بيد الله؛ إن شاء أن يبعثنا بعثَنا، قال: فانصرف رسول الله حين قلت له ذلك ولم يرجع إليّ شيئًا، ثم سمعته يَضرب فخذه ويقول: ﴿وَكَانَ ٱلۡإِنسَٰنُ أَكۡثَرَ شَيۡءٍ جَدَلًا﴾. ابن عاشور:١٥/٣٤٨.\nالناصح بخير يُقابل بالقبول قدر المستطاع، وضح ذلك.\nوَكَانَ ٱلۡإِنسَٰنُ أَكۡثَرَ شَيۡءٖ جَدَلٗا ٥٤\nكثير من الناس يجادلون في الحق بعد ما تبين، ويجادلون بالباطل ليدحضوا به الحق؛ ولهذا قال: ﴿وَكَانَ ٱلۡإِنسَٰنُ أَكۡثَرَ شَيۡءٍ جَدَلًا﴾ أي: مجادلة ومنازعة فيه، مع أن ذلك غير لائق بهم، ولا عدل منهم. والذي أوجب له ذلك وعدم الإيمان بالله إنَّما هو الظلم والعناد، لا لقصور في بيانه وحجته وبرهانه. السعدي:٤٨٠.\nكثرة المجادلة مع العلماء وطلبة العلم هل هي من الخير في شيء؟ وما السبب الذي يجعل الإنسان يكثر من الجدال مع أهل الحق؟\nوَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۚ وَيُجَٰدِلُ ٱلَّذِينَ كَفَرُواْ بِٱلۡبَٰطِلِ لِيُدۡحِضُواْ بِهِ ٱلۡحَقَّۖ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَمَآ أُنذِرُواْ هُزُوٗا ٥٦\nففرّق بين الآيات الدالة على العلم التي يعلم بالعقل أنها دلائل للرب، وبين النُذُر: وهو الإخبار عن المخوف؛ كإخبار الأنبياء بما يستحقه العصاة من العذاب؛ فهذا يعلم بالخبر والنذر. ابن تيمية:٤/٢٦٠.\nما الفرق بين الآيات والنذر؟\nوَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۚ\n﴿وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ﴾ أي: بالجنة لمن آمن، (ومنذرين) أي: مخوفين بالعذاب من كفر. القرطبي:١٣/٣١١.\nاذكر أسلوبين من أساليب الدعوة إلى الله تعالى جاء ذكرهما في الآية.\nوَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعۡرَضَ عَنۡهَا وَنَسِيَ مَا قَدَّمَتۡ يَدَاهُۚ إِنَّا جَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۖ وَإِن تَدۡعُهُمۡ إِلَى ٱلۡهُدَىٰ فَلَن يَهۡتَدُوٓاْ إِذًا أَبَدٗا ٥٧\nوفي هذه الآية من التخويف لمن ترك الحق بعد علمه أن يحال بينهم وبينه، ولا يتمكن منه بعد ذلك، ما هو أعظم مرهب وزاجر عن ذلك. السعدي:٤٨١.\nهناك فرقٌ بين من يعرض عن الحق وهو عالم به، ومن هو جاهل به، تحدث عن ذلك في ضوء هذه الآية.\nوَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعۡرَضَ عَنۡهَا وَنَسِيَ مَا قَدَّمَتۡ يَدَاهُۚ\nأي: لا أحد أظلم لنفسه ممن وعظ بآيات ربه، فتهاون بها، وأعرض عن قبولها. القرطبي:١٣/٣١٢.\nمن أظلم الناس لنفسه؟\nوَإِذۡ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبۡرَحُ حَتَّىٰٓ أَبۡلُغَ مَجۡمَعَ ٱلۡبَحۡرَيۡنِ أَوۡ أَمۡضِيَ حُقُبٗا ٦٠\nفي هذا من الفقه: رحلة العالم في طلب الازدياد من العلم، والاستعانة على ذلك بالخادم والصاحب، واغتنام لقاء الفضلاء والعلماء -وإن بعدت أقطارهم- وذلك كان دأب السلف الصالح، وبسبب ذلك وصل المرتحلون إلى الحظ الراجح، وحصلوا على السعي الناجح؛ فرسخت لهم في العلوم أقدام، وصح لهم من الذكر والأجر والفضل أفضل الأقسام. قال البخاري: ورحل جابر بن عبد الله مسيرة شهر إلى عبد الله بن أنيس -رضي الله عنهم- في حديث. القرطبي:١٣/٣١٨.\nماذا يتعلم طالب العلم من رحلة موسى -عليه الصلاة والسلام-؟"],[301,"§الكهف\nwords\nأَوَينَالَجَأنَا.\nنَبغِنطلُب.\nفَارتَدَّافَرَجَعَا.\nخَرَقَهَاقَلَعَ لَوحًا مِن أَلوَاحِهَا.\nإِمرًاأَمرًا مُنكَرًا.\nنُكرًامُنكَرًا عَظِيمًا.\ndeeds\nسل الله تعالى أن يرزقك الرحمة بالخلق والعلم بالخالق؛ فإن أعلم الناس بربه هو أرحمهم بخلقه.\nولاية الله تنال بأمور؛ منها: مصاحبة أوليائه، ومصاحبة أوليائه تحتاج إلى حسن الخلق.\nاقرأ كتابًا يتعلق بأدب طالب العلم، وتأمل فيه، وامتثل ما فيه.\nguid\nالسماع والقراءة والتأمل أسباب فقط، ومؤتي العلم هو الله سبحانه.\nقد يصدر عن الشيخ عتاب ليرى مقدار تحمل الطالب وعلو همته.\nتأمل هذه القصة المشتملة على الرحلة في طلب العلم؛ ففيها من العبر الكثير.\nrefl\nءَاتِنَا غَدَآءَنَا\nاستحباب إطعام الإنسان خادمَه من مأكله، وأكلهما جميعًا؛ لأن ظاهر قوله: ﴿ءَاتِنَا غَدَآءَنَا﴾ -إضافةً إلى الجميع- أنه أكل هو وهو جميعًا. السعدي:٤٨٣.\nفي الآية تنبيهٌ على بعض الآداب في التعامل مع الخدام، بيِّن ذلك.\nفَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدۡ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبٗا ٦٢\nوفي هذا دليل على جواز الإخبار بما يجده الإنسان من الألم والأمراض، وأن ذلك لا يقدح في الرضا، ولا في التسليم للقضاء، لكن إذا لم يصدر ذلك عن ضجر ولا سخط. القرطبي:١٣/٣٢٢.\nهل يعد الإخبار بالحال اعتراضًا على القدر؟\nوَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيۡطَٰنُ أَنۡ أَذۡكُرَهُۥۚ\nإضافة الشر وأسبابه إلى الشيطان على وجه التسويل والتزيين، وإن كان الكل بقضاء الله وقدره. السعدي:٤٨٣.\nلماذا نسب النسيان إلى الشيطان، مع أن ذلك بتقدير الله -سبحانه وتعالى-؟\nقَالَ لَهُۥ مُوسَىٰ هَلۡ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدٗا ٦٦\nسؤال تلطف، لا على وجه الإلزام والإجبار، وهكذا ينبغي أن يكون سؤال المتعلم من العالم. ابن كثير:٣/٩٤.\nفي الآية أدبٌ يجب على المتعلم أن يتحلى به مع العالم، فما هو؟\nقَالَ لَهُۥ مُوسَىٰ هَلۡ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدٗا ٦٦\nالعلم النافع هو العلم المرشد إلى الخير؛ فكل علم يكون فيه رشد وهداية لطرق الخير، وتحذير عن طريق الشر، أو وسيلة لذلك، فإنه من العلم النافع، وما سوى ذلك؛ فإما أن يكون ضارًا، أو ليس فيه فائدة؛ لقوله: ﴿تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدًا﴾. السعدي:٤٨٤.\nلمَ طلب موسى من الخضر أن يُعَلِّمَهُ رشدًا، ولم يطلب منه أن يعلمه أي علم؟\nقَالَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا ٦٧\nوفي هذا أصل من أصول التعليم: أن ينبِه المعلمُ المتعلمَ بعوارض موضوعات العلوم الملقنة؛ لا سيما إذا كانت في معالجتها مشقة. ابن عاشور:١٥/٣٧٢.\nفي الآية الكريمة أصل من أصول التعليم، فما هو؟\nقَالَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا ٦٧\nأي: إنك لا تقدر على مصاحبتي؛ لما ترى مني من الأفعال التي تخالف شريعتك. ابن كثير:٣/٩٤.\nلمَ لم يصبر موسى على أعمال الخضر؟"],[302,"§الكهف\nwords\nاستَطعَمَا أَهلَهَاطَلَبَا طَعامًا عَلَى سَبِيلِ الضِّيَافَةِ.\nيُرِيدُ أَن يَنقَضَّيُوشِكُ أَن يَسقُطَ.\nبِتَأوِيلِبِمَآلِ وَعَاقِبَةِ.\nيُرهِقَهُمَايُكَلِّفَهُمَا وَيُحَمِّلَهُمَا.\nزَكَاةًصَلاَحًا، وَطَهَارَةً.\nوَأَقرَبَ رُحمًابِرًّا بِهِمَا، وَرَحمَةً عَلَيهِمَا.\nذِي القَرنَينِمَلِكٍ صَالِحٍ عَادِلٍ مَلَكَ مَا بَينَ المَشرِقِ وَالمَغرِبِ.\ndeeds\nاعمل اليوم عملًا صالحًا؛ يصل نفعه إلى الآخرين.\nاجتهد هذا اليوم في دفع ظلم عن مظلوم أو ضعيف.\nاسأل الله تعالى صلاح ذريتك.\nguid\nالصبر شرط لطلب العلم.\nحسن تدبير الله تعالى لأوليائه بما ظاهره ألمٌ، ولكن في باطنه رحمة.\nإصلاح الأب لنفسه سبب في صلاح ذريته ورزقهم.\nrefl\nقَالَ إِن سَأَلۡتُكَ عَن شَيۡءِۢ بَعۡدَهَا فَلَا تُصَٰحِبۡنِيۖ قَدۡ بَلَغۡتَ مِن لَّدُنِّي عُذۡرٗا ٧٦\nوهنا لم يعتذر موسى بالنسيان: إما لأنه لم يكن نَسِي، ولكنه رجّح تغيير المنكر العظيم -وهو قتل النفس بدون موجب- على واجب الوفاء بالالتزام، وإما لأنّه نسي وأعرض عن الاعتذار بالنسيان لسماجة تكرر الاعتذار به. ابن عاشور:١٦/٦.\nلماذا لم يعتذر موسى -عليه السلام- بالنسيان مرة أخرى؟\nأَمَّا ٱلسَّفِينَةُ فَكَانَتۡ لِمَسَٰكِينَ يَعۡمَلُونَ فِي ٱلۡبَحۡرِ فَأَرَدتُّ أَنۡ أَعِيبَهَا وَكَانَ وَرَآءَهُم مَّلِكٞ يَأۡخُذُ كُلَّ سَفِينَةٍ غَصۡبٗا ٧٩\nالقاعدة الكبيرة أيضًا وهي: (أن عمل الإنسان في مال غيره إذا كان على وجه المصلحة وإزالة المفسدة؛ أنه يجوز، ولو بلا إذن، حتى ولو ترتب على عمله إتلاف بعض مال الغير)؛ كما خرق الخضر السفينة لتعيب، فتسلم من غصب الملك الظالم. فعلى هذا: لو وقع حرق، أو غرق، أو نحوهما في دار إنسان أو ماله، وكان إتلاف بعض المال أو هدم بعض الدار فيه سلامة للباقي جاز للإنسان، بل شُرع له ذلك. السعدي:٤٨٥.\nاستنبط العلماء من هذه الآية قاعدةً مهمة، فما هي؟\nوَأَمَّا ٱلۡغُلَٰمُ فَكَانَ أَبَوَاهُ مُؤۡمِنَيۡنِ فَخَشِينَآ أَن يُرۡهِقَهُمَا طُغۡيَٰنٗا وَكُفۡرٗا ٨٠\nقال قتادة: \"قد فرح به أبواه حين وُلِد، وحزنًا عليه حين قُتِل، ولو بقي لكان فيه هلاكهما؛ فليرضَ امرؤٌ بقضاء الله؛ فإن قضاء الله للمؤمن فيما يكره خيرٌ له من قضائه فيما يحب\". ابن كثير:٣/٩٦.\nالمسلم تصيبه الأحزان والمصائب، فكيف عليه أن يتعامل معها؟\nوَكَانَ أَبُوهُمَا صَٰلِحٗا فَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا\nفيه دليل على أن الرجل الصالح يحفظ في ذريته، [وتشملهم بركة عبادته] في الدنيا والآخرة بشفاعته فيهم، ورفع درجتهم إلى أعلى درجة في الجنة لتقر عينه بهم. ابن كثير:٣/٩٧.\nعملك الصالح قد يُفِيدُ ذريتك، وضح ذلك من خلال الآية؟\nوَكَانَ أَبُوهُمَا صَٰلِحٗا فَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا\nففيها ما يدل على أن الله تعالى يحفظ الصالح في نفسه وفي ولده، وإن بعدوا عنه، وقد روي أن الله تعالى يحفظ الصالح في سبعة من ذريته. القرطبي:١٣/٣٥٦\nما الثمرة العاجلة لصلاح المرء واستقامته؟\nفَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةٗ مِّن رَّبِّكَۚ\n﴿فَأَرَادَ رَبُّكَ﴾: أسند الإرادة هنا إلى الله لأنها في أمر مغيب مستأنف، لا يعلم ما يكون منه إلا الله، وأسند الخضر إلى نفسه في قوله: ﴿فَأَرَدتُّ أَنۡ أَعِيبَهَا﴾؛ لأنها لفظة عيب، فتأدب بأن لا يسندها إلى الله، وذلك كقول إبراهيم -عليه السلام-: ﴿وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ﴾ [الشعراء: ٨٠]. ابن جزي:١/٥١٨.\nلمَ أسند الخضر الإرادة إليه في خرق السفينة، بينما أسندها إلى الله في إقامة الجدار؟\nوَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِيۚ ذَٰلِكَ تَأۡوِيلُ مَا لَمۡ تَسۡطِع عَّلَيۡهِ صَبۡرٗا ٨٢\n﴿وَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِيۚ﴾ أي: باختياري ورأيي، بل فعلته بأمر الله. البغوي:٣/٥٥.\nهل يفعل العالم والقدوة ما يريد، أم يتبع ويمتثل أمر الله تعالى؟"],[303,"§الكهف\nwords\nسَبَبًاأَسبَابًا وَطُرُقًا تُوَصِّلُهُ إِلَى مَا يُرِيدُ مِن فَتحِ المُدُنِ، وَقَهرِ الأَعدَاءِ.\nفَأَتبَعَ سَبَبًاأَخَذَ جَادًّا بِالأَسبَابِ وَالطُّرُقِ المُوصِلَةِ إِلَى مَا يُريدُ.\nحَمِئَةٍحَارَّةٍ ذَاتِ طِينٍ أَسوَدَ.\nنُكرًاعَظِيمًا.\nخَرجًاأَجرًا.\nرَدمًاسَدًّا.\ndeeds\nاستخرج ثلاث فوائد وعِبر من خلال قراءتك لقصة ذي القرنين.\nاستعذ بالله من فتنة يأجوج ومأجوج.\nساعد اليوم أحد الضعفاء والمحتاجين.\nguid\nإذا رأيت شرًّا أو باطلًا أو فسادًا، فأَدِّ واجب النصيحة.\nاعترف دائمًا بفضل الله تعالى عليك مهما بلغ عزك ومالك وجاهك.\nالأمور الكبار تواجه بالتعاون بين الناس: هذا برأيه، وهذا بماله، وهذا بجهده.\nrefl\nإِنَّا مَكَّنَّا لَهُۥ فِي ٱلۡأَرۡضِ وَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءٖ سَبَبٗا ٨٤\nهذه القصة القرآنية تعطي صفات لا محيد عنها؛ إحداها: أنه كان ملكًا صالحًا عادلًا. الثانية: أنه كان مُلهمًا من الله. الثالثة: أن ملكه شمل أقطارًا شاسعةً. الرابعة: أنه بلغ في فتوحه من جهة المغرب مكانا كان مجهولًا؛ وهو عين حمئة. ابن عاشور:١٦/٢٠.\nقد يجمع الله للعبد بين نعم الدنيا والآخرة، وضح ذلك من خلال الآية.\nوَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءٖ سَبَبٗا ٨٤\nوهذه الأسباب التي أعطاه الله إياها لم يخبرنا الله ولا رسوله -صلى الله عليه وسلم- بها، ولم تتناقلها الأخبار على وجه يفيد العلم؛ فلهذا لا يسعنا غير السكوت عنها. السعدي:٤٨٥.\nما موقفنا مما سكت الله ورسوله عنه؟\nوَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءٖ سَبَبٗا ٨٤ فَأَتۡبَعَ سَبَبًا ٨٥\nأي: استعملها على وجهها؛ فليس كل من عنده شيء من الأسباب يسلكه، ولا كل أحد يكون قادرًا على السبب؛ فإذا اجتمع القدرة على السبب الحقيقي والعمل به حصل المقصود، وإن عدمًا أو أحدهما لم يحصل. السعدي:٤٨٥.\nمتى يستطيع الإنسان الاستفادة من الأسباب؟\nقُلۡنَا يَٰذَا ٱلۡقَرۡنَيۡنِ إِمَّآ أَن تُعَذِّبَ وَإِمَّآ أَن تَتَّخِذَ فِيهِمۡ حُسۡنٗا ٨٦\nمعنى هذا: أن الله تعالى مكنه منهم، وحكَّمه فيهم، وأظفره بهم، وخيَّره: إن شاء قتل وسبى، وإن شاء مَنَّ أو فدى، فعرف عدله وإيمانه فيما أبداه. ابن كثير:٥/١٩٣.\nالمؤمنون هم أرحم الخلق بالخلق، وضح ذلك من خلال الآية.\nوَأَمَّا مَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗا فَلَهُۥ جَزَآءً ٱلۡحُسۡنَىٰۖ وَسَنَقُولُ لَهُۥ مِنۡ أَمۡرِنَا يُسۡرٗا ٨٨\nأي: فله الجنة والحالة الحسنة عند الله جزاء يوم القيامة. ﴿وَسَنَقُولُ لَهُۥ مِنۡ أَمۡرِنَا يُسۡرًا﴾ أي: وسنحسن إليه، ونلطف له بالقول، ونيسر له المعاملة. وهذا يدل على كونه من الملوك الصالحين، الأولياء العادلين العالمين؛ حيث وافق مرضاة الله في معاملة كل أحد بما يليق بحاله. السعدي:٤٨٥.\nما علامة التوفيق للأمير الصالح؟\nقَالُواْ يَٰذَا ٱلۡقَرۡنَيۡنِ إِنَّ يَأۡجُوجَ وَمَأۡجُوجَ مُفۡسِدُونَ فِي ٱلۡأَرۡضِ فَهَلۡ نَجۡعَلُ لَكَ خَرۡجًا عَلَىٰٓ أَن تَجۡعَلَ بَيۡنَنَا وَبَيۡنَهُمۡ سَدّٗا ٩٤ قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرٞ فَأَعِينُونِي بِقُوَّةٍ أَجۡعَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَدۡمًا ٩٥\nفي هذه الآية دليل على أن الملك فرض عليه أن يقوم بحماية الخلق في حفظ بيضتهم، وسد فرجتهم، وإصلاح ثغورهم من أموالهم التي تفيء عليهم، وحقوقهم التي تجمعها خزانتهم تحت يده ونظره، حتى لو أكلتها الحقوق وأنفذتها المؤن لكان عليهم جبر ذلك من أموالهم، وعليه حسن النظر لهم؛ وذلك بثلاثة شروط؛ الأول: ألا يستأثر عليهم بشيء. الثاني: أن يبدأ بأهل الحاجة؛ فيعينهم. الثالث: أن يسوي في العطاء بينهم على قدر منازلهم. القرطبي:٣١/٣٨٤-٣٨٥.\nبيّن الواجب على من ولاه الله تعالى ولاية أو إمارة تجاه من تحته.\nقَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرٞ فَأَعِينُونِي بِقُوَّةٍ أَجۡعَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَدۡمًا ٩٥\nالمعنى: قال لهم ذو القرنين: ما بسطه الله تعالى لي من القدرة والملك خير من خرجكم وأموالكم. القرطبي: ١٣/٣٨٤.\nهل افتتن ذو القرنين بملكه، فافتخر بقوته ونسي المنعم -جل وعلا-؟"],[304,"§الكهف\nwords\nدَكَّاءَمُنهَدِمًا مُستَوِيًا بِالأَرضِ.\nفَحَبِطَتفَبَطَلَت.\nحِوَلًاتَحَوُّلًا.\nلَنَفِدَلَفَنِيَ وَفَرَغَ.\nمَدَدًاحِبرًا.\ndeeds\nكلما انتهيت اليوم من عبادة فادعُ الله أن يتقبلها منك.\nاستعذ بالله من الشرك والبدعة والرياء؛ فإنها مفسدات للأعمال.\nعدد الأعمال الصالحة الواردة في سورة الكهف، واعمل واحدًا منها؛ لعلك تنال الفردوس من الجنة.\nguid\nكلما ساعدت غيرك فاحمد الله على أن وفقك لهذا العمل.\nلا قيمة ولا وزن لعمل لا يوافق رضا الله تعالى وقبوله.\nالعمل الصالح هو الذي يجمع بين الإخلاص والمتابعة للرسول -صلى الله عليه وسلم- بالدليل الصحيح، و ما عدا ذلك فهو مردود وإن بدا صالحًا.\nrefl\nوَعَرَضۡنَا جَهَنَّمَ يَوۡمَئِذٖ لِّلۡكَٰفِرِينَ عَرۡضًا ١٠٠\nيعرض عليهم جهنم، أي: يبرزها لهم، ويظهرها؛ ليروا ما فيها من العذاب والنكال قبل دخولها؛ ليكون ذلك أبلغ في تعجيل الهم والحزن لهم. ابن كثير:٣/١٠٤.\nلماذا تُعرَضُ جهنم للكافرين في عرصات يوم القيامة قبل أن يدخلوها؟\nٱلَّذِينَ كَانَتۡ أَعۡيُنُهُمۡ فِي غِطَآءٍ عَن ذِكۡرِي وَكَانُواْ لَا يَسۡتَطِيعُونَ سَمۡعًا ١٠١\nأي: لا يقدرون على سمع آيات الله الموصلة إلى الإيمان؛ لبغضهم القرآن والرسول -صلى الله عليه وسلم-؛ فإن المبغض لا يستطيع أن يلقي سمعه إلى كلام من أبغضه، فإذا انحجبت عنهم طرق العلم والخير فليس لهم سمع ولا بصر ولا عقل نافع. السعدي:٤٨٧.\nما السبب الذي جعل المبغضين للدين لا يستطيعون سماع آيات القرآن سماعًا ينتفعون به؟\nأَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓاْ أَن يَتَّخِذُواْ عِبَادِي مِن دُونِيٓ أَوۡلِيَآءَۚ إِنَّآ أَعۡتَدۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ نُزُلٗا ١٠٢\nوإطلاق اسم النزل على العذاب استعارة علاقتها التهكم. ابن عاشور:١٦/٤٥.\nما وجه إطلاق اسم النزل على العذاب؟\nقُلۡ هَلۡ نُنَبِّئُكُم بِٱلۡأَخۡسَرِينَ أَعۡمَٰلًا ١٠٣ ٱلَّذِينَ ضَلَّ سَعۡيُهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ يَحۡسَبُونَ أَنَّهُمۡ يُحۡسِنُونَ صُنۡعًا ١٠٤\nفيه دلالة على أن من الناس من يعمل العمل ويظن أنه محسن، وقد حبط سعيه. والذي يوجب إحباط السعي: إما فساد الاعتقاد، أو المراءاة. القرطبي:١٣/٣٩٢.\nقد يُحبط عمل العبد وهو لا يشعر؛ فما الأسباب؟\nأُوْلَٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَلِقَآئِهِۦ فَحَبِطَتۡ أَعۡمَٰلُهُمۡ فَلَا نُقِيمُ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَزۡنٗا ١٠٥\nوجُعل عدم إقامة الوزن مفرعًا على حبط أعمالهم؛ لأنهم بحبط أعمالهم صاروا محقرين، لا شيء لهم من الصالحات. ابن عاشور:١٦/٤٨.\nلِمَ لَم يكن للكافرين وزن يوم القيامة؟\nلَا يَبۡغُونَ عَنۡهَا حِوَلٗا ١٠٨\nأي: تحولًا ولا انتقالًا؛ لأنهم لا يرون إلا ما يعجبهم ويبهجهم، ويسرهم ويفرحهم، ولا يرون نعيمًا فوق ما هم فيه. السعدي:٤٨٨.\nلمَ لا يريد أهل الجنة التحول عنها إلى شيء آخر؟\nقُلۡ إِنَّمَآ أَنَا۠ بَشَرٞ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ\nقال ابن عباس -رضي الله عنهما-: \"علَّم الله رسوله -صلى الله عليه وسلم- التواضع؛ لئلَّا يزهو على خلقه\"؛ فأمره أن يُقرَّ، فيقول: إني آدمي مثلكم، إلا أني خصصت بالوحي وأكرمني الله به. البغوي:٣/٧٠.\nبيّن ما يدل على أهمية التواضع من هذه الآية."],[305,"§مريم\nwords\nنَادَىدَعَا.\nوَهَنَضَعُفَ\nالمَوَالِيَأَقَارِبِي وَعَصَبَتِي.\nعَاقِرًالاَ تَلِدُ.\nعِتِيًّاالنِّهَايَةَ فِي الكِبَرِ وَاليُبسِ.\nبُكرَةً وَعَشِيًّاصَبَاحًا، وَمَسَاءً.\ndeeds\nحدد أمرًا صعب عليك، ثم نادِ ربك به نداءً خفيًّا؛ محسنًا الظن به.\nسل الله تعالى أن يرزقك الذرية الصالحة، وأن يجعل ذريتك من أولياء الله تعالى.\nأكثِر من ذكر الله تعالى في الصباح والمساء.\nguid\nأحسن الظن بالله تعالى؛ فالله سبحانه عند حسن ظن عبده به.\nتأمل في إجابة الله تعالى لدعاء من دعاه، يدفعك ذلك للإكثار من التضرع إليه.\nلا تقس رغباتك بقدرتك، وإنَّما قسها بقدرة الله تعالى.\nrefl\nذِكۡرُ رَحۡمَتِ رَبِّكَ عَبۡدَهُۥ زَكَرِيَّآ ٢\nوصفه بالعبودية تشريفًا له، وإعلامًا له بتخصيصه وتقريبه. ابن جزي:٢/٣.\nلِم وصف الله زكريا -عليه السلام- بالعبودية؟\nإِذۡ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيّٗا ٣\n﴿إِذۡ نَادَىٰ رَبَّهُۥ﴾ يعني: دعاه. ﴿نِدَآءً خَفِيًّا﴾: أخفاه لأنه يسمع الخفي كما يسمع الجهر، ولأن الإخفاء أقرب إلى الإخلاص وأبعد من الرياء، ولئلَّا يلومه الناس على طلب الولد. ابن جزي:٢/٣.\nفي وصف النداء بالخفي مناسبة لطيفة اشتملت على عدة أمور، بينها.\nقَالَ رَبِّ إِنِّي وَهَنَ ٱلۡعَظۡمُ مِنِّي وَٱشۡتَعَلَ ٱلرَّأۡسُ شَيۡبٗا\nتوسل إلى الله تعالى بضعفه وعجزه، وهذا من أحب الوسائل إلى الله؛ لأنه يدل على التبري من الحول والقوة، وتعلق القلب بحول الله وقوته. السعدي:٤٨٩.\nفي قصة زكريا بيانٌ لوسيلة ناجعة من وسائل الدعاء؛ فما هي؟\nقَالَ رَبِّ إِنِّي وَهَنَ ٱلۡعَظۡمُ مِنِّي وَٱشۡتَعَلَ ٱلرَّأۡسُ شَيۡبٗا وَلَمۡ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيّٗا ٤\nقال العلماء: يستحب للمرء أن يذكر في دعائه نعم الله تعالى عليه، وما يليق بالخضوع؛ لأن قوله تعالى: ﴿وَهَنَ ٱلۡعَظۡمُ مِنِّي﴾ إظهار للخضوع، وقوله: ﴿وَلَمۡ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيًّا﴾ إظهار لعادات تفضله في إجابته أدعيته؛ أي: لم أكن بدعائي إياك شقيًّا؛ أي: لم تكن تخيب دعائي إذا دعوتك؛ أي: إنك عودتني الإجابة فيما مضى. القرطبي:١٣/٤٠٩.\nبيّن ما ينبغي أن يكون عليه المتضرع إذا دعا الله تعالى.\nوَإِنِّي خِفۡتُ ٱلۡمَوَٰلِيَ مِن وَرَآءِي وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا فَهَبۡ لِي مِن لَّدُنكَ وَلِيّٗا ٥ يَرِثُنِي وَيَرِثُ مِنۡ ءَالِ يَعۡقُوبَۖ\nوجه خوفه: أنه خشي أن يتصرفوا من بعده في الناس تصرفًا سيئًا، فسأل الله ولدًا يكون نبيًا من بعده؛ ليسوسهم بنبوته ما يوحى إليه، فأجيب في ذلك، لا أنه خشي من وراثتهم له ماله؛ فإن النبي أعظم منزلة، وأجل قدرًا من أن يشفق على ماله إلى ما هذا حَدُّهُ. ابن كثير:٣/١٠٩.\nهل كان نبي الله زكريا يخشى على ماله أن يأخذه بعد موته الوارثون الذين ليسوا بأبناء؛ كما يفعله أهل الدنيا اليوم؟ وهل الأنبياء أصلًا يورثون؟\nيَٰزَكَرِيَّآ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ ٱسۡمُهُۥ يَحۡيَىٰ لَمۡ نَجۡعَل لَّهُۥ مِن قَبۡلُ سَمِيّٗا ٧\nفتضمنت هذه البشرى ثلاثة أشياء؛ أحدها: إجابة دعائه، وهي كرامة. الثاني: إعطاؤه الولد؛ وهو قوة، الثالث: أن يفرد بتسميته. القرطبي:١٣/٤١٧.\nما البشائر التي ساقها الله تعالى لنبيه زكريا -عليه السلام- بعد تضرعه؟\nقَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمٞ وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا وَقَدۡ بَلَغۡتُ مِنَ ٱلۡكِبَرِ عِتِيّٗا ٨\nتعجب واستبعاد أن يكون له ولد مع شيخوخته وعقم امرأته؛ فسأل ذلك أولًا لعلمه بقدرة الله عليه، وتعجب منه لأنه نادر في العادة. وقيل: سأله وهو في سِن من يرجوه، وأجيب بعد ذلك بسنين وهو قد شاخ. ابن جزي:٢/٤.\nكيف تعجب زكريا من بشارة الله له بالولد، مع كونه هو الذي دعا بذلك؟"],[306,"§مريم\nwords\nخُذِ الكِتَابالتَّورَاةَ.\nبِقُوَّةٍبِجِدٍّ، وَاجتِهَادٍ؛ حِفظًا، وَفَهمًا، وَعَمَلًا.\nالحُكمَالحِكمَةَ وَحُسنَ الفَهمِ وَالعَمَلِ.\nوَحَنَانًارَحمَةً وَمَحَبَّةً.\nانتَبَذَتاعتَزَلَت وَابتَعَدَت.\nفَأَجَاءَهَافَأَلجَأَهَا.\nالمَخَاضُطَلقُ الحَملِ.\nسَرِيًّاجَدوَلَ مَاءٍ.\nجَنِيًّاغَضًّا جُنِيَ مِن سَاعَتِهِ.\ndeeds\nاحرص على القوة في الالتزام بدينك، وإياك واللعب في الالتزام بأحكامه.\nمريم لمَّا فزعت عندما رأت جبريل استغاثت بالله، سبحانه ولم تستغث بغيره.\nعليك ببذل السبب، ولا تتواكل.\nguid\nقدم لوالديك شيئًا يحبانه.\nكل من تخاف أذاه فاستعذ اليوم بالله منه.\nتصبح بسبع تمرات.\nrefl\nوَبَرَّۢا بِوَٰلِدَيۡهِ وَلَمۡ يَكُن جَبَّارًا عَصِيّٗا ١٤\nيقول تعالى ذكره: وكان برًّا بوالديه، مسارعًا في طاعتهما ومحبتهما، غير عاق بهما، ﴿وَلَمۡ يَكُن جَبَّارًا عَصِيًّا﴾: يقول جل ثناؤه: ولم يكن مستكبرًا عن طاعة ربه وطاعة والديه، ولكنه كان لله ولوالديه متواضعًا متذلّلًا؛ يأتمر لما أُمر به، وينتهي عما نُهي عنه، لا يعصي ربه، ولا والديه. الطبري:١٨/١٦٠.\nهذه الآية فيها حقان، فما هما؟\nوَسَلَٰمٌ عَلَيۡهِ يَوۡمَ وُلِدَ وَيَوۡمَ يَمُوتُ وَيَوۡمَ يُبۡعَثُ حَيّٗا ١٥\nقال سفيان بن عيينة: \"أوحش ما يكون المرء في ثلاثة مواطن: يوم يولد؛ فيرى نفسه خارجًا مما كان فيه. ويوم يموت؛ فيرى قومًا لم يكن عاينهم. ويوم يبعث؛ فيرى نفسه في محشر عظيم\"، قال: \"فأكرم الله فيها يحيى بن زكريا، فخصه بالسلام عليه\". ابن كثير:٣/١١١.\nلماذا خصت هذه المواطن الثلاثة بذكر السلام فيها على النبي يحيى -عليه السلام-؟\nقَالَتۡ إِنِّيٓ أَعُوذُ بِٱلرَّحۡمَٰنِ مِنكَ إِن كُنتَ تَقِيّٗا ١٨\nتذكير له بالله؛ وهذا هو المشروع في الدفع: أن يكون بالأسهل فالأسهل؛ فخوفته أولًا بالله -عز وجل-. ابن كثير:٣/١١٣.\nما الطريقة المثلى لدفع المعتدي على الإنسان؟\nقَالَتۡ إِنِّيٓ أَعُوذُ بِٱلرَّحۡمَٰنِ مِنكَ إِن كُنتَ تَقِيّٗا ١٨\nوذكرها صفة (الرحمن) دون غيرها من صفات الله؛ لأنها أرادت أن يرحمها الله بدفع من حسبته داعرًا عليها. ابن عاشور:١٦/٨١.\nلماذا خصت مريم -عليها السلام- صفة (الرحمن) دون غيرها؟\nوَلِنَجۡعَلَهُۥٓ ءَايَةٗ لِّلنَّاسِ\nتدل على كمال قدرة الله تعالى، وعلى أن الأسباب جميعها لا تستقل بالتأثير، وإنَّما تأثيرها بتقدير الله؛ فيري عباده خرق العوائد في بعض الأسباب العادية لئلَّا يقفوا مع الأسباب، ويقطعوا النظر عن مُقَدِّرها ومسببها. السعدي:٤٩١.\nقصة مريم وابنها، تجعل القلوب متعلقة بالله وحده دون الأسباب الدنيوية، وضح ذلك.\nوَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا ٢٥\nاستدل بعض الناس بهذه الآية على أن الإنسان ينبغي له أن يتسبب في طلب الرزق؛ لأن الله أمر مريم بهز النخلة. ابن جزي:٢/٦.\nيستفاد من الآية أنه على العبد أن يتسبب في طلب الرزق، وضح ذلك.\nوَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبٗا جَنِيّٗا ٢٥ فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنٗاۖ\nوقد أخذ بعض العلماء من هذه الآية أن خير ما تطعمه النفساء الرُّطَب؛ قالوا: لو كان شيء أحسن للنفساء من الرُّطَب لأطعمه الله مريم وقت نفاسها بعيسى، قاله الربيع بن خثيم وغيره. الشنقيطي:٣/٣٩٩.\nفي هذه الآية منهج طبي يقدمه القرآن فما هو؟"],[307,"§مريم\nwords\nوَقَرِّي عَينًاوَطِيبِي نَفسًا.\nفَرِيًّا أَمرًاعَظِيمًا مُفتَرىً.\nبَغِيًّازَانِيَةً.\nمُبَارَكًاعَظِيمَ الخَيرِ وَالنَّفعِ.\nيَمتَرُونَيَشُكُّونَ.\nالأَحزَابُالفِرَقُ مِن أَهلِ الكِتَابِ.\nفَوَيلٌفَهَلاَكٌ.\nمَشهَدِشُهُودِ.\nأَسمِع بِهِم وَأَبصِرمَا أَشَدَّ سَمعَهُم وَبَصَرَهُم.\ndeeds\nدافع اليوم عن مظلوم بالوسيلة التي تستطيع.\nأدِّ الصلوات مع الجماعة، ثم أدِّ السنن الرواتب.\nاقرأ في قصة عيسى -عليه السلام- من أحد المصادر الصحيحة.\nguid\nلا تتعجل بحكم السوء على الصالحين؛ فلعل وراء الأمور ما هو خافٍ عليك.\nتمسك بالصلاة والزكاة ما دام فيك نفسٌ يتردد؛ فإن ذلك شعارُ الأنبياء والصالحين من قبل.\nبِرُّ الوالدين من صفات الأنبياء والصالحين.\nrefl\nفَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيّٗا ٢٦\nوإنَّما لم تؤمر بمخاطبتهم في نفي ذلك عن نفسها لأن الناس لا يصدقونها، ولا فيه فائدة، وليكون تبرئتها بكلام عيسى في المهد أعظم شاهد على براءتها؛ فإن إتيان المرأة بولد من دون زوج، ودعواها أنه من غير أحد من أكبر الدعاوى التي لو أقيم عدة من الشهود لم تصدق بذلك، فجُعلت بينة هذا الخارق للعادة أمرًا من جنسه؛ وهو كلام عيسى في حال صغره جدًا. السعدي:٤٩٢.\nلماذا أمرت مريم -عليها السلام- ألا تكلم أحدًا من الناس بشأن عيسى؟\nفَأَتَتۡ بِهِۦ قَوۡمَهَا تَحۡمِلُهُ\nأتت بعيسى قومها تحمله؛ وذلك لعلمها ببراءة نفسها وطهارتها. السعدي:٤٩٢.\nكيف تجرأت مريم -عليها السلام- على أن تأتي قومها حاملة عيسى مع أنها لم تتزوج؟\nقَالَ إِنِّي عَبۡدُ ٱللَّهِ ءَاتَىٰنِيَ ٱلۡكِتَٰبَ وَجَعَلَنِي نَبِيّٗا ٣٠\nذكر -جل وعلا- في هذه الآية الكريمة أن أول كلمة نطق لهم بها عيسى وهو صبي في مهده: أنه عبد الله؛ وفي ذلك أعظم زجر للنصارى عن دعواهم أنه الله، أو ابنه، أو إله معه. الشنقيطي:٣/٤١٦.\nما الذي تفهمه من أول كلمة نطق بها عيسى -عليه الصلاة والسلام-؟\nقَالَ إِنِّي عَبۡدُ ٱللَّهِ\nفخاطبهم بوصفه بالعبودية، وأنه ليس فيه صفة يستحق بها أن يكون إلهًا، أو ابنًا للإله، تعالى الله عن قول النصارى المخالفين لعيسى في قوله. السعدي:٤٩٢.\nلماذا كان أول ما نطق به عيسى -عليه السلام-: ﴿إِنِّي عَبۡدُ ٱللَّهِ﴾؟\nوَجَعَلَنِي مُبَارَكًا أَيۡنَ مَا كُنتُ\nأي: نفّاعًا حيث ما توجهت، وقال مجاهد: \"معلمًا للخير\"، وقال عطاء: \"أدعو إلى اللّه، وإلى توحيده وعبادته\". البغوي:٣/٨٥.\nكيف يكون العبد مباركًا حيثما كان؟\nوَبَرَّۢا بِوَٰلِدَتِي وَلَمۡ يَجۡعَلۡنِي جَبَّارٗا شَقِيّٗا ٣٢\nوقد خصه الله تعالى بذلك بين قومه؛ لأن برّ الوالدين كان ضعيفًا في بني إسرائيل يومئذ، وبخاصة الوالدة؛ لأنها تُستضعف؛ لأن فرط حنانها ومشقتها قد يجرئان الولد على التساهل في البرّ بها. ابن عاشور:١٦/١٠٠.\nلماذا خص بر عيسى -عليه السلام- بوالدته بالذكر؟\nوَٱلسَّلَٰمُ عَلَيَّ يَوۡمَ وُلِدتُّ وَيَوۡمَ أَمُوتُ وَيَوۡمَ أُبۡعَثُ حَيّٗا ٣٣\nوذكر المواطن التي خصها؛ لأنها أوقات حاجة الإنسان إلى رحمة الله. ابن عطية:٤/١٥.\nوضح سبب تخصيص هذه المواطن بالذكر من عيسى -عليه الصلاة والسلام-."],[308,"§مريم\nwords\nالحَسرَةِالنَّدَامَةِ.\nصِدِّيقًاعَظِيمَ الصِّدقِ لاَ يَكذِبُ.\nصِرَاطًا سَوِيًّاطَرِيقًا لاَ عِوَجَ فِيهِ.\nمَلِيًّازَمَنًا طَوِيلًا.\nحَفِيًّارَحِيمًا بِحَالِي يُكرِمُنِي و يُجِيبُنِي إِذَا دَعَوتُهُ.\nمُخلَصًامُصطَفىً مُختَارًا.\ndeeds\nاحتسب الأجر على بلاء أصابك؛ فقد ابتلي إبراهيم بكفر أبيه فصبر على قضاء الله وقدره، فوهبه الله النبوة في ذريته.\nقصة إبراهيم في دعوته مع أبيه مليئة بالفوائد، حاول أن تدونها في عدة نقاطٍ، وأرسلها لمن حولك.\nسل الله تعالى المغفرة والرضوان لوالديك.\nguid\nعبادة الأصنام والقبور والأضرحة تعدُّ عبادةً للشيطان؛ لأنه الآمر بها، والداعي إليها.\nلا تأنف من أخذ العلم عمن صغر سِنُّه، أو قلت درجته عنك.\nاعتزل أماكن الفساد والشر، ولا تتساهل في ذلك.\nrefl\nوَأَنذِرۡهُمۡ يَوۡمَ ٱلۡحَسۡرَةِ إِذۡ قُضِيَ ٱلۡأَمۡرُ وَهُمۡ فِي غَفۡلَةٖ وَهُمۡ لَا يُؤۡمِنُونَ ٣٩\nالحسرة: أشد الندم والتلف على الشيء الذي فات ولا يمكن تداركه، والإنذار: الإعلام المقترن بتهديد؛ أي: أنذر الناس يوم القيامة، وقيل له يوم الحسرة لشدة ندم الكفار فيه على التفريط، وقد يندم فيه المؤمنون على ما كان منهم من التقصير. الشنقيطي:٣/٤٢٢.\nلماذا سمي يوم القيامة يوم الحسرة؟ وهل الحسرة خاصة بالكفار؟\nوَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِبۡرَٰهِيمَۚ إِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيًّا ٤١\nالصدّيق: الكثير الصدق القائم عليه، وقيل: من صدّق الله في وحدانيته، وصدّق أنبياءه ورسله، وصدّق بالبعث، وقام بالأوامر فعمل بها؛ فهو الصدّيق. البغوي:٣/٨٨.\nكيف يكون العبد صدّيقًا؟\nيَٰٓأَبَتِ لِمَ تَعۡبُدُ مَا لَا يَسۡمَعُ وَلَا يُبۡصِرُ وَلَا يُغۡنِي عَنكَ شَيۡـٔٗا ٤٢ يَٰٓأَبَتِ إِنِّي قَدۡ جَآءَنِي مِنَ ٱلۡعِلۡمِ مَا لَمۡ يَأۡتِكَ فَٱتَّبِعۡنِيٓ أَهۡدِكَ صِرَٰطٗا سَوِيّٗا ٤٣ يَٰٓأَبَتِ لَا تَعۡبُدِ ٱلشَّيۡطَٰنَۖ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلرَّحۡمَٰنِ عَصِيّٗا ٤٤ يَٰٓأَبَتِ إِنِّيٓ أَخَافُ أَن يَمَسَّكَ عَذَابٞ مِّنَ ٱلرَّحۡمَٰنِ فَتَكُونَ لِلشَّيۡطَٰنِ وَلِيّٗا ٤٥\nفتدرج الخليل -عليه السلام- بدعوة أبيه بالأسهل فالأسهل؛ فأخبره بعلمه وأن ذلك موجب لاتباعك إياي، وأنك إن أطعتني اهتديت إلى صراط مستقيم، ثم نهاه عن عبادة الشيطان، وأخبره بما فيها من المضار، ثم حذره عقاب الله ونقمته إن أقام على حاله، وأنه يكون وليًا للشيطان. السعدي:٤٩٥.\nالتدرج في الدعوة من أهم الأمور التي يجب أن يحرص عليها الداعية، فكيف نستفيد هذا الأمر من قصة إبراهيم؟\nيَٰٓأَبَتِ إِنِّي قَدۡ جَآءَنِي مِنَ ٱلۡعِلۡمِ مَا لَمۡ يَأۡتِكَ\nوفي هذا من لطف الخطاب ولينه ما لا يخفى؛ فإنه لم يقل: \"يا أبت أنا عالم وأنت جاهل\"، أو \"ليس عندك من العلم شيء\"، وإنَّما أتى بصيغة تقتضي أن عندي وعندك علمًا، وأن الذي وصل إليَّ لم يصل إليك ولم يأتك. السعدي:٤٩٤.\nكيف يستفيد الداعية من هذه الآية في مخاطباته للناس حال دعوته؟\nيَٰٓأَبَتِ لَا تَعۡبُدِ ٱلشَّيۡطَٰنَۖ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلرَّحۡمَٰنِ عَصِيّٗا ٤٤\nوذكر وصف: (عصيًّا) الذي هو من صيغ المبالغة في العصيان، مع زيادة فعل (كان) للدلالة على أنه لا يفارق عصيان ربه، وأنه متمكن منه. ابن عاشور:١٦/١١٧.\nلمَ وصف الشيطان بـــــ (عصيًّا)؟\nقَالَ سَلَٰمٌ عَلَيۡكَۖ سَأَسۡتَغۡفِرُ لَكَ رَبِّيٓۖ\nأجابه الخليل جواب عباد الرحمن عند خطاب الجاهلين، ولم يشتمه، بل صبر، ولم يقابل أباه بما يكره، وقال: ﴿سَلَٰمٌ عَلَيۡكَۖ﴾. السعدي:٤٩٥.\nكيف يكون أدب الداعية إلى الله إذا قُوبِلَ بالأذى والكلام السيئ؟\nوَأَعۡتَزِلُكُمۡ وَمَا تَدۡعُونَ مِن دُونِ ٱللَّهِ وَأَدۡعُواْ رَبِّي عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّي شَقِيّٗا ٤٨\nوهذه وظيفة من أَيِسَ مِمَّن دعاهم... أن يشتغل بإصلاح نفسه، ويرجو القبول من ربه، ويعتزل الشر وأهله. السعدي:٤٩٥.\nما الذي يفعله الداعية إذا لم يجد القبول عند من يدعوه؟"],[309,"§مريم\nwords\nالطُّورجَبَلٌ بِسَينَاءَ.\nنَجِيًّامُنَاجِيًا لَنَا.\nوَإِسرَائِيلَيَعقُوبَ -عليه السلام-.\nوَاجتَبَينَااصطَفَينَا.\nخَلفٌأَتبَاعُ سُوءٍ.\nغَيًّاشَرًّا وَخَيبَةً فِي جَهَنَّمَ.\nمَأتِيًّاآتِيَا لاَ مَحَالَةَ.\nلَغوًابَاطِلًا.\ndeeds\nمُر إخوانك وأهل بيتك بالصلاة والصدقة، وذكرهم بأدائها في وقتها.\nابك أو تباك عند قراءة القرآن؛ خصوصًا إذا كنت وحدك.\nتذكر ذنبًا فعلته، وألح على الله بالاستغفار والتوبة منه.\nguid\nاحرص على الصدق في أقوالك، وأفعالك، ومواعيدك، وعهودك؛ فذلك من أخلاق الأنبياء.\nتفقد أحوال الأهل والأقارب في صلاتهم وزكاتهم من صفات الأنبياء والصالحين.\nتعاهد صلاتك بين الفينة والأخرى، وتفقد حالك معها؛ فإن إضاعتها إضاعة للدين بأكمله.\nrefl\nوَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِسۡمَٰعِيلَۚ إِنَّهُۥ كَانَ صَادِقَ ٱلۡوَعۡدِ وَكَانَ رَسُولٗا نَّبِيّٗا ٥٤\nقال مجاهد: \"لم يَعِد شيئًا إلا وفّى به\"، وقال مقاتل: \"وعد رجلًا أن يقيم مكانه حتى يرجع إليه الرجل، فأقام إسماعيل مكانه ثلاثة أيام للميعاد؛ حتى رجع إليه الرجل\". البغوي:٣/٩١.\nبيّن قيمة الوفاء بالوعد عند الأنبياء -عليهم الصلاة والسلام-.\nوَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِسۡمَٰعِيلَۚ إِنَّهُۥ كَانَ صَادِقَ ٱلۡوَعۡدِ وَكَانَ رَسُولٗا نَّبِيّٗا ٥٤ وَكَانَ يَأۡمُرُ أَهۡلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ\nفكمَّل نفسه، وكمَّل غيره، وخصوصًا أخص الناس عنده، وهم أهله؛ لأنهم أحق بدعوته من غيرهم. السعدي:٤٩٦.\nلماذا خُصَّ الأهل بالذكر هنا؟\nإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُ ٱلرَّحۡمَٰنِ خَرُّواْۤ سُجَّدٗاۤ وَبُكِيّٗا۩ ٥٨\nوفي إضافة الآيات إلى اسمه (الرحمن) دلالة على أن آياته من رحمته بعباده وإحسانه إليهم؛ حيث هداهم بها إلى الحق، وبصرهم من العمى، وأنقذهم من الضلالة، وعلمهم من الجهالة. السعدي:٤٩٦.\nما الذي يستفاد من إضافة الآيات إلى اسم الله (الرحمن)؟\nفَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٌ أَضَاعُواْ ٱلصَّلَوٰةَ وَٱتَّبَعُواْ ٱلشَّهَوَٰتِۖ فَسَوۡفَ يَلۡقَوۡنَ غَيًّا ٥٩\nسألوا ابن مسعود عن إضاعتها فقال: \"هو تأخيرها حتى يخرج وقتها\"، فقالوا: ما كنا نرى ذلك إلا تركها، فقال: \"لو تركوها لكانوا كفارًا\". ابن تيمية:٤/٢٨٥.\nبيّن خطورة تأخير الصلاة عن وقتها.\nفَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٌ أَضَاعُواْ ٱلصَّلَوٰةَ\nوإذا أضاعوها فهم لما سواها من الواجبات أضيع؛ لأنها عماد الدين، وقوامه، وخير أعمال العباد. ابن كثير:٣/١٢٥.\nتخصيص الصلاة بالذكر في الآية تنبيهٌ على أمر مهم، فما هو؟\nجَنَّٰتِ عَدۡنٍ ٱلَّتِي وَعَدَ ٱلرَّحۡمَٰنُ عِبَادَهُۥ بِٱلۡغَيۡبِۚ\nأضافها إلى اسمه (الرحمن) لأنها فيها من الرحمة والإحسان ما لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر. وأيضًا ففي إضافتها إلى رحمته ما يدل على استمرار سرورها، وأنها باقية بقاء رحمته التي هي أثرها وموجبها. السعدي:٤٩٧.\nما الذي يستفاد من اقتران ذكر الجنات باسمه (الرحمن) في هذه الآية؟\nوَلَهُمۡ رِزۡقُهُمۡ فِيهَا بُكۡرَةٗ وَعَشِيّٗا ٦٢\n﴿بُكۡرَةً وَعَشِيًّا﴾ أي: في قدر هذين الوقتين، إذ لا بكرة ثَمَّ ولا عشيًّا... وقال العلماء: ليس في الجنة ليل ولا نهار، وإنَّما هم في نور أبدًا. القرطبي:١٣/٤٧٩.\nكيف يكون رزق أهل الجنة بكرة وعشيًّا؟ وهل في الجنة نهار وليل؟"],[310,"§مريم\nwords\nجِثِيًّابَارِكِينَ عَلَى رُكَبِهِم مِنَ الهَولِ.\nعِتِيًّاتَمَرُّدًا وَعِصيَانًا.\nصِلِيًّادُخُولًا، وَمُقَاسَاةً لِحَرِّهَا.\nوَارِدُهَامَارًّا بِالصِّرَاطِ المَنصُوبِ عَلَى مَتنِ جَهَنَّمَ.\nنَدِيًّامَجلِسًا.\nأَثَاثًامَتَاعًا.\nوَرِئيًامَنظَرًا، وَمَرأىً.\nمَرَدًّامَرجِعًا، وَعَاقِبَةً.\ndeeds\nاستعذ بالله من عذاب جهنم؛ فقد ثبت ورودك لها لكن لم يثبت لك النجاة منها.\nسل الله تعالى أن يجعلك ممن زاده هدى.\nقل: \"سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر\"؛ فهي من الباقيات الصالحات.\nguid\nالعبادة تحتاج إلى صبر ومجاهدة؛ فدرب نفسك على ذلك.\nالجزاء من جنس العمل؛ فيقدم رؤساء الضلالة وأئمة الكفر إلى جهنم قبل الأتباع.\nكل من سعى إلى علم أو عمل صالح وهو جاد وصادق هداه الله إلى علم وعمل صالح آخر.\nrefl\nفَوَرَبِّكَ لَنَحۡشُرَنَّهُمۡ وَٱلشَّيَٰطِينَ ثُمَّ لَنُحۡضِرَنَّهُمۡ حَوۡلَ جَهَنَّمَ جِثِيّٗا ٦٨\nوعطف (الشياطين) على ضمير المشركين لقصد تحقيرهم بأنهم يحشرون مع أحقر جنس وأفسده، وللإشارة إلى أن الشياطين هم سبب ضلالهم الموجب لهم هذه الحالة. ابن عاشور:١٦/١٤٧.\nما فائدة عطف (الشياطين) على ضمير المشركين في الآية الكريمة؟\nثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِيعَةٍ أَيُّهُمۡ أَشَدُّ عَلَى ٱلرَّحۡمَٰنِ عِتِيّٗا ٦٩\n﴿أَيُّهُمۡ أَشَدُّ عَلَى ٱلرَّحۡمَٰنِ عِتِيًّا﴾: عتوًا؛ قال ابن عباس -رضي الله عنهما-: \"يعني جرأة\". وقال مجاهد: \"فجورا\"؛ يريد: الأعتى فالأعتى. وقال الكلبي: \"قائدهم ورأسهم في الشر\"؛ يريد أنه يقدم في إدخال النار من هو أكبر جرمًا وأشد كفرًا. وفي بعض الآثار: أنهم يحشرون جميعا حول جهنم مسلسلين مغلولين، ثم يقدم الأكفر فالأكفر. البغوي:٣/٩٩\nبيّن عقوبة من كان إمامًا في الشر والطغيان.\nوَإِن مِّنكُمۡ إِلَّا وَارِدُهَاۚ كَانَ عَلَىٰ رَبِّكَ حَتۡمٗا مَّقۡضِيّٗا ٧١\nكان عبد الله بن رواحة واضعًا رأسه في حجر امرأته فبكى، فبكت امرأته، فقال: ما يبكيك؟ قالت: رأيتك تبكي فبكيت، قال: إني ذكرت قول الله -عز وجل-: ﴿وَإِن مِّنكُمۡ إِلَّا وَارِدُهَاۚ﴾ \"فلا أدري أنجو منها، أم لا\". وكان أبو ميسرة إذا أوى إلى فراشه قال: \"يا ليت أمي لم تلدني\"، ثم يبكي، فقيل له: ما يبكيك يا أبا ميسرة؟ فقال: \"أُخبِرنا أَنَّا واردوها، ولم نُخبَر أَنَّا صادرون عنها\". ابن كثير:٣/١٢٩.\nلم يخاف المتدبر للقرآن من الورود على النار؟\nوَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُوٓاْ أَيُّ ٱلۡفَرِيقَيۡنِ خَيۡرٞ مَّقَامٗا وَأَحۡسَنُ نَدِيّٗا ٧٣\n﴿خَيۡرٌ مَّقَامًا﴾ أي: في الدنيا من: كثرة الأموال، والأولاد، وتوفر الشهوات... وعُلم من هذا أن الاستدلال على خير الآخرة بخير الدنيا من أفسد الأدلة، وأنه من طرق الكفار. السعدي:٤٩٩.\nكثيرًا ما يجعل الناس النعم الدنيوية دليلًا على محبة الله لهم، فما رأيك في هذا؟\nوَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَحۡسَنُ أَثَٰثٗا وَرِءۡيٗا ٧٤\nالأثاث: المال من اللباس ونحوه، والرئي: المنظر، فأخبر أن الذين أهلكهم قبلهم كانوا أحسن صورًا، وأحسن أثاثًا وأموالًا؛ ليبين أن ذلك لا ينفع عنده، ولا يعبأ به. ابن تيمية:٤/٢٩٢.\nلا تجدي الأموال والصور نفعًا عند الله -عز وجل-، بين ذلك من الآية الكريمة.\nقُلۡ مَن كَانَ فِي ٱلضَّلَٰلَةِ فَلۡيَمۡدُدۡ لَهُ ٱلرَّحۡمَٰنُ مَدًّاۚ حَتَّىٰٓ إِذَا رَأَوۡاْ مَا يُوعَدُونَ إِمَّا ٱلۡعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعۡلَمُونَ مَنۡ هُوَ شَرّٞ مَّكَانٗا وَأَضۡعَفُ جُندٗا ٧٥\nفمعيار التفرقة بين النّعمة الناشئة عن رضى الله تعالى على عبده وبين النعمة التي هي استدراج لمن كفر به هو النظر إلى حال من هو في نعمة بين حال هدى وحال ضلال. ابن عاشور:١٦/١٥٥.\nكيف نفرق بين من كان في نعمة لرضى الله تعالى، ومن كان في نعمة للاستدراج؟\nوَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٞ مَّرَدًّا ٧٦\n﴿وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ﴾: الأذكار والأعمال الصالحة التي تبقى لصاحبها. البغوي:٣/١٠٥.\nما الباقيات الصالحات؟ ولِم سميت بذلك؟"],[311,"§مريم\nwords\nأَفَرَأَيتَأَعَلِمتَ؟!\nوَنَمُدُّ لَهُنَزِيدُ لَهُ.\nتَؤُزُّهُم أَزًّاتَدفَعُهُم عَنِ الطَّاعَةِ، وَتُغرِيهِم بِالمَعصِيَةِ.\nوِردًامُشَاةً عِطَاشًا.\nيَتَفَطَّرنَيَتَشَقَّقنَ.\nوَتَخِرُّ الجِبَالُ هَدًّاتَسقُطُ سُقُوطًا شَدِيدًا.\ndeeds\nتعاهد نفسك هذا اليوم أن لا تقول إلا ما يرضي الله سبحانه، وتذكر قول الله تعالى.\nقل: \"أعوذ بالله السميع العليم من الشيطان الرجيم\"؛ فإن للشيطان أزًّا للباطل، فمن استعاذ بالله تعالى منه أعاذه.\nادع الله تعالى أن يحشرك في زمرة المتقين.\nguid\nكل من صرف عبادة لغير الله سبحانه فسيكون من صرفها له عدوًا له يوم القيامة.\nيسارع الكافرون والمنافقون إلى الشر والفساد والشهوات لوجود شياطين تحركهم وتدفعهم إليها.\nلا تجامل قريبًا ولا بعيدًا في العبادة؛ فإنك ستأتي الله فردًا يوم القيامة.\nrefl\nوَنَرِثُهُۥ مَا يَقُولُ وَيَأۡتِينَا فَرۡدٗا ٨٠\nأي: نسلبه ما أعطيناه في الدنيا من مال وولد، وقال ابن عباس -رضي الله عنهما- وغيره: \"أي: نرثه المال والولد بعد إهلاكنا إياه\". وقيل: نحرمه ما تمناه في الآخرة من مال وولد، ونجعله لغيره من المسلمين. ﴿وَيَأۡتِينَا فَرۡدًا﴾ أي: منفردًا لا مال له، ولا ولد، ولا عشيرة تنصره. القرطبي:١٣/٥٠٩.\nحينما ترى في الواقع من اغتر بماله وجاهه وولده، وظن أنه مخلد، كيف تعظه بهذه الآيات؟\nوَنَرِثُهُۥ مَا يَقُولُ وَيَأۡتِينَا فَرۡدٗا ٨٠\nومعنى إرث أولاده: أنهم يصيرون مسلمين، فيدخلون في حزب الله؛ فإن العاص وَلدَ عمَرًا الصحابي الجليل، وهشامًا الصحابي الشهيد يوم أجنادين؛ فهنا بشارة للنبي -صلى الله عليه وسلم-، ونكاية وكمد للعاص بن وائل. ابن عاشور:١٦/١٦٣.\nما معنى إرث أولاد العاص بن وائل السهمي المذكور في الآية الكريمة؟\nوَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةٗ لِّيَكُونُواْ لَهُمۡ عِزّٗا ٨١ كَلَّاۚ سَيَكۡفُرُونَ بِعِبَادَتِهِمۡ وَيَكُونُونَ عَلَيۡهِمۡ ضِدًّا ٨٢\nما علق العبد رجاءه وتوكله بغير الله إلا خاب من تلك الجهة، ولا استنصر بغير الله إلا خُذِل. ابن تيمية:٤/٢٩٢.\nما علق العبد رجاءه وتوكله بغير الله إلا خاب من تلك الجهة، كيف دلت الآية الكريمة على ذلك؟\nيَوۡمَ نَحۡشُرُ ٱلۡمُتَّقِينَ إِلَى ٱلرَّحۡمَٰنِ وَفۡدٗا ٨٥\nالوافد لا بد أن يكون في قلبه من الرجاء وحسن الظن بالوافد إليه ما هو معلوم؛ فالمتقون يفدون إلى الرحمن راجين منه رحمته وعميم إحسانه، والفوز بعطاياه في دار رضوانه. السعدي:٥٠٠.\nما ظن المتقين بربهم يوم القيامة حين يحشرون إليه؟\nوَنَسُوقُ ٱلۡمُجۡرِمِينَ إِلَىٰ جَهَنَّمَ وِرۡدٗا ٨٦\nيساقون إلى جهنم وردًا؛ أي: عطاشًا، وهذا أبشع ما يكون من الحالات؛ سوقهم على وجه الذل والصغار إلى أعظم سجن وأفظع عقوبة -وهو جهنم- في حال ظمئهم ونصبهم. السعدي:٥٠٠.\nفي الآية تصوير لحالة المشركين البشعة يوم القيامة، فبينها.\nلَّا يَمۡلِكُونَ ٱلشَّفَٰعَةَ إِلَّا مَنِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَٰنِ عَهۡدٗا ٨٧\nوسمى الله الإيمان به واتباع رسله عهدًا؛ لأنه عهد في كتبه وعلى ألسنة رسله بالجزاء الجميل لمن اتبعهم. السعدي:٥٠١.\nما وجه تسمية الإيمان بالله ورسله عهدًا؟\nتَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِنۡهُ وَتَنشَقُّ ٱلۡأَرۡضُ وَتَخِرُّ ٱلۡجِبَالُ هَدًّا ٩٠ أَن دَعَوۡاْ لِلرَّحۡمَٰنِ وَلَدٗا ٩١\nقال ابن عباس: \"إن الشرك فزعت منه السماوات والأرض والجبال وجميع الخلائق، إلا الثقلين\". ابن كثير:٣/١٣٥.\nالجبال والشجر أعقل من بعض البشر، وضح ذلك من خلال الآية."],[312,"§مريم ، طه\nwords\nوُدًّامَحَبَّةً فِي قُلُوبِ عِبَادِهِ.\nلُدًّاشَدِيدِي الخُصُومَةِ بِالبَاطِلِ.\nقَرنٍأُمَّةٍ.\nرِكزًاصَوتًا خَفِيًّا.\nالثَّرَىالتُّرَابِ النَّدِيِّ؛ وَالمُرَادُ: الأَرَضُونَ السَّبعُ؛ لأِنَّهَا تَحتَهُ.\nبِقَبَسٍبِشُعلَةٍ تَستَدفِئُونَ بِهَا.\ndeeds\nاقرأ سورة مريم، واستخرج منها بشارتين ونذارتين.\nأرسل رسالة تبين فيها أقرب طريق وأيسره ذكرته الآية لنيل حب الناس.\nتعرف على صفات الله تعالى الواردة في سورة طه، وادع الله بمقتضاها؛ فقل: \"يا رحمن ارحمني، يا غني ارزقني\".\nguid\nتأمل في الأمم الغابرة التي أهلكها الله تعالى؛ هل تسمع لهم صوتًا؟! هل ترى لهم أثرًا؟!\nتَعَلُّم اللغة العربية عبادة؛ لأنها توصل لفهم القرآن الكريم.\nتذكر أن الله تعالى مطّلع على السرائر والخفيّات، فلا تقل ولا تفعل ما يسخطه سبحانه.\nrefl\nإِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَيَجۡعَلُ لَهُمُ ٱلرَّحۡمَٰنُ وُدّٗا ٩٦\nقال مجاهد: \"يحبهم الله، ويحببهم إلى عباده المؤمنين\"... قال هرم بن حيان: \"ما أقبل عبد بقلبه إلى الله -عز وجل- إلا أقبل الله بقلوب أهل الإيمان إليه؛ حتى يرزقه مودتهم\". البغوي:٣/١١٠.\nكيف ينال العبد الود مِن الله تعالى، ومن عباده؟\nإِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَيَجۡعَلُ لَهُمُ ٱلرَّحۡمَٰنُ وُدّٗا ٩٦\nيجعل لهم ودًا: أي: محبة وودادًا في قلوب أوليائه، وأهل السماء والأرض، وإذا كان لهم في القلوب ودٌ تيسر لهم كثيرٌ من أمورهم، وحصل لهم من الخيرات، والدعوات، والإرشاد، والقبول، والإمامة ما حصل. السعدي:٥٠١.\nما الفائدة التي يستفيدها المسلم من محبة الصالحين له؟\nفَإِنَّمَا يَسَّرۡنَٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ ٱلۡمُتَّقِينَ وَتُنذِرَ بِهِۦ قَوۡمٗا لُّدّٗا ٩٧\nأي: القرآن؛ يعني: بيناه بلسانك العربي، وجعلناه سهلًا على من تدبره وتأمله. القرطبي:١٣/٥٢٨.\nهل مشروع تدبر القرآن الذي تعيش معه صعب، أم سهل؟\nمَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ لِتَشۡقَىٰٓ ٢ إِلَّا تَذۡكِرَةٗ لِّمَن يَخۡشَىٰ ٣\nوالتذكرة: الموعظة التي تلين لها القلوب، فتمتثل أمر الله، وتجتنب نهيه، وخص بالتذكرة من يخشى دون غيرهم؛ لأنهم هم المنتفعون بها. الشنقيطي:٤/٥.\nما الصفة التي تهيئك للاستفادة من التذكير والمواعظ؟\nإِلَّا تَذۡكِرَةٗ لِّمَن يَخۡشَىٰ ٣\nوالتذكرة: خطور المنسي بالذهن؛ فإن التوحيد مستقرّ في الفطرة والإشراك مناف لها، فالدعوة إلى الإسلام تذكير لما في الفطرة، أو تذكير لملّة إبراهيم -عليه السلام-. ابن عاشور:١٦/١٨٥.\nلماذا قال سبحانه تذكرة، ولم يقل تعليمًا؟\nوَإِن تَجۡهَرۡ بِٱلۡقَوۡلِ فَإِنَّهُۥ يَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى ٧\nعن ابن عباس وسعيد بن جبير -رضي الله عنهم-: \"السر ما تسر في نفسك، وأخفى من السر ما يلقيه -عز وجل- في قلبك من بعد، ولا تعلم أنك ستحدّث به نفسك؛ لأنك تعلم ما تسر به اليوم، ولا تعلم ما تسر به غدًا، واللّه يعلم ما أسررت اليوم، وما تسر به غدًا\". وقال علي بن أبي طلحة عن ابن عباس -رضي الله عنهما-: \"(السر): ما أسر ابن آدم في نفسه، (وأخفى): ما خفي عليه مما هو فاعله قبل أن يعمله\". البغوي:٣/١١٣.\nبيّن عظيم قدرة الله في علمه السر وأخفى.\nوَهَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ ٩\nوفي ذكر قصة موسى بأسرها في هذه السورة تسلية للنبي عما لقي في تبليغه من المشقات وكفر الناس؛ فإنما هي له على جهة التمثيل في أمره. ابن عطية:٤/٣٨.\nقصة موسى في سورة طه تبعث على السكينة والطمأنينة، تدبرها ثم استخرج فائدتين منها."],[313,"§طه\nwords\nفَتَردَىفَتَهلِكَ.\nأَتَوَكَّأُ عَلَيهَاأَعتَمِدُ عَلَيهَا فِي المَشيِ.\nوَأَهُشُّ بِهَا عَلَى غَنَمِيأَهُزُّ بِهَا الشَّجَرَ؛ لِتَرعَى غَنَمِي مَا يَتَسَاقَطُ مِن وَرَقِهِ.\nمَآرِبُمَنَافِعُ، وَحَاجَاتٌ.\nسُوءٍبَرَصٍ.\nوَاحلُل عُقدَةًأَطلِق لِسَانِي بِفَصِيحِ المَنطِقِ.\nاشدُد بِهِ أَزرِيقَوِّنِي بِهِ، وَشُدَّ بِهِ ظَهرِي.\ndeeds\nسجِّل في ورقة أهم النقاط التي تعين الداعية في دعوته من خلال قصة موسى -عليه السلام-.\nابحث عن صـاحب صالح مناسب لك، واشترك معه في عمل دعوي.\nتعاهد نفسك هذا اليوم بأذكار الصباح والمساء، وأدبار الصلوات، وعند النوم.\nguid\nالحذر الحذر من قطاع الطريق بينك وبين الله سبحانه.\nالعمل على كسب العيش وفعل الأسباب من سنة الأنبياء -عليهم السلام-.\nعلى العبد قبل أن يبدأ بأي عمل أن يطلب العون والتوفيق من الله.\nrefl\nإِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ ١٤\n(فاعبدني): بجميع أنواع العبادة: ظاهرها وباطنها، أصولها وفروعها، ثم خص الصلاة بالذكر -وإن كانت داخلة في العبادة- لفضلها وشرفها، وتضمنها عبودية القلب واللسان والجوارح. السعدي:٥٠٣.\nلماذا خُصَّت الصلاة بالذكر مع أنها داخلة في العبادة؟\nإِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ ١٤\nقيل: المعنى لتذكرني فيها، وقيل: لأذكرك بها. ابن جزي:٢/١٦.\nدلت الآية على مقصد عظيم من مقاصد الصلاة، فما هو؟\nوَمَا تِلۡكَ بِيَمِينِكَ يَٰمُوسَىٰ ١٧\nإنَّما سأله ليريه عظيم ما يفعله في العصا من قلبها حية؛ فمعنى السؤال: تقرير أنها عصا، فيتبين له الفرق بين حالها قبل أن يقلبها، وبعد أن قلبها. ابن جزي:٢/١٧.\nما الغرض من سؤال الله -جل وعلا- لموسى، مع كونه تعالى يعلم السر وأخفى؟\nٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ ٢٤ قَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي ٢٥ وَيَسِّرۡ لِيٓ أَمۡرِي ٢٦\nولما علم موسى ذلك لم يبادر بالمراجعة في الخوف من ظلم فرعون، بل تلقى الأمر، وسأل الله الإعانة عليه بما يؤول إلى رباطة جأشه، وخلق الأسباب التي تعينه على تبليغه، وإعطائه فصاحة القول للإسراع بالإقناع بالحجة. ابن عاشور:١٦/٢١٠.\nبيّن سرعة الأنبياء -عليهم السلام- في التسليم والقبول لأمر الله تعالى.\nرَبِّ ٱشۡرَحۡ لِي صَدۡرِي ٢٥\nأي: وسِّعه وأفسِحه لأتحمل الأذى القولي والفعلي، ولا يتكدر قلبي بذلك، ولا يضيق صدري؛ فإن الصدر إذا ضاق لم يصلح صاحبه لهداية الخلق ودعوتهم. السعدي:٥٠٤.\nفي الآية حثٌّ للدعاة أن يدعوا الله أن يزيل الهموم الثقيلة عنهم قبل مباشرة الدعوة، وضِّح ذلك.\nقَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي ٢٥ وَيَسِّرۡ لِيٓ أَمۡرِي ٢٦\nسأل اللّه أن يوسع قلبه للحق؛ حتى يعلم أن أحدًا لا يقدر على مضرّته إلا بإذن اللّه، وإذا علم ذلك لم يخف فرعون مع شدة شوكته وكثرة جنوده. البغوي:٣/١١٩.\nما سنة الأنبياء في معالجة الهموم الكبيرة والعقبات الشديدة في الدعوة إلى الله؟\nوَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي ٢٧ يَفۡقَهُواْ قَوۡلِي ٢٨\nوذلك لما كان أصابه من اللثغ حين عرض عليه التمرة والجمرة فأخذ الجمرة فوضعها على لسانه... وما سأل أن يزول ذلك بالكلية، بل بحيث يزول العِيُّ، ويحصل لهم فهم ما يريد منه، وهو قدر الحاجة، ولو سأل الجميع لزال، ولكن الأنبياء لا يسألون إلا بحسب الحاجة. ابن كثير:٣/١٤٣.\nفي الآية بيانٌ لأدب من آداب دعاء الأنبياء لربهم في حاجاتهم الدنيوية، فما هو؟"]])